}

/* Key compiler flags for Cortex-M4F */
// -mcpu=cortex-m4       Target CPU
// -mthumb               Thumb-2 instruction set
// -mfpu=fpv4-sp-d16     Single-precision FPU
// -mfloat-abi=hard      Hardware floating point ABI
// -Wall -Wextra          Full warnings
// -ffunction-sections    Enable linker garbage collection
// -fdata-sections        Enable linker garbage collection
// -Og (debug) / -O2 (release)   Optimization level

/* Pseudo-code of startup sequence */
extern uint32_t _sidata, _sdata, _edata, _sbss, _ebss;  /* Linker symbols */
extern void SystemInit(void);
extern int main(void);

void Reset_Handler(void) {
    /* Step 1: Copy .data section from flash (ROM) to RAM */
    uint32_t *src = &_sidata;    /* Flash address of .data initializers */
    uint32_t *dst = &_sdata;     /* RAM start of .data */
    while (dst < &_edata) {
        *dst++ = *src++;
    }

    /* Step 2: Zero-fill .bss section in RAM */
    dst = &_sbss;
    while (dst < &_ebss) {
        *dst++ = 0;
    }

    /* Step 3: Call system initialization (clock, flash latency) */
    SystemInit();

    /* Step 4: Call C main function */
    main();

    /* Step 5: Infinite loop if main returns (should not happen) */
    while (1) {}
}

int main(void) {
    /* 1. Configure flash latency BEFORE increasing clock speed */
    HAL_Init();   /* Sets flash wait states, enables prefetch */

    /* 2. Configure clock tree: HSE -> PLL -> 168 MHz */
    SystemClock_Config();

    /* 3. Initialize peripherals needed for basic operation */
    GPIO_Init();    /* Debug LEDs, timing pins */
    UART_Init();    /* Debug console */

    /* 4. Create all RTOS kernel objects */
    xHeartbeatQueue = xQueueCreate(4, sizeof(uint32_t));
    configASSERT(xHeartbeatQueue != NULL);

    /* 5. Create all tasks */
    BaseType_t ret;
    ret = xTaskCreate(vHeartbeatTask, "HB",  256, NULL, 2, NULL);
    configASSERT(ret == pdPASS);

    ret = xTaskCreate(vMonitorTask,   "Mon", 512, NULL, 4, NULL);
    configASSERT(ret == pdPASS);

    /* 6. Start the scheduler (does not return on success) */
    vTaskStartScheduler();

    /* 7. Execution reaches here only if scheduler start failed */
    configASSERT(0);   /* Trap: insufficient heap for idle task */
    for (;;) {}
}

void vHeartbeatTask(void *pvParameters) {
    (void)pvParameters;
    TickType_t xLastWakeTime = xTaskGetTickCount();
    const TickType_t xPeriod = pdMS_TO_TICKS(500);

    for (;;) {
        vTaskDelayUntil(&xLastWakeTime, xPeriod);
        HAL_GPIO_TogglePin(GPIOD, GPIO_PIN_12);  /* Green LED */
    }
}

static uint32_t monitor_count = 0;

void vMonitorTask(void *pvParameters) {
    (void)pvParameters;
    TickType_t xLastWakeTime = xTaskGetTickCount();
    const TickType_t xPeriod = pdMS_TO_TICKS(100);

    for (;;) {
        vTaskDelayUntil(&xLastWakeTime, xPeriod);
        monitor_count++;
        HAL_GPIO_TogglePin(GPIOD, GPIO_PIN_15);  /* Blue LED */

        if (monitor_count % 50 == 0) {
            printf("[MON] count=%lu heap=%u tick=%lu\r\n",
                   monitor_count,
                   (unsigned)xPortGetFreeHeapSize(),
                   (unsigned long)xTaskGetTickCount());
        }
    }
}

/* rtos_hooks.c - FreeRTOS callback implementations */

void vApplicationStackOverflowHook(TaskHandle_t xTask, char *pcTaskName) {
    (void)xTask;
    /* Log or signal the fault */
    printf("STACK OVERFLOW: %s\r\n", pcTaskName);
    /* Enter safe state */
    taskDISABLE_INTERRUPTS();
    for (;;) {}
}

void vApplicationMallocFailedHook(void) {
    printf("MALLOC FAILED\r\n");
    taskDISABLE_INTERRUPTS();
    for (;;) {}
}

void vApplicationIdleHook(void) {
    /* Optional: enter low-power mode or collect statistics */
}

void vApplicationTickHook(void) {
    /* Optional: called from tick interrupt context */
}

