/* Context switch time (us) ≈ (t2 - t1) / 168  (168 cycles per us at 168 MHz) */

void vApplicationIdleHook(void)
{
    /* Enter sleep mode; CPU wakes on next interrupt (SysTick or peripheral) */
    __WFI();
}

void vTaskA(void *pvParameters)
{
    for (;;)
