                              TickType_t xTicksToWait );

if( xQueueSend( xSensorQueue, &xReading, pdMS_TO_TICKS( 50 ) ) != pdPASS )
{
    /* Queue full for 50 ms --- log overflow, increment error counter */
    ulQueueOverflowCount++;
}

BaseType_t xQueueReceive( QueueHandle_t xQueue,
                          void *pvBuffer,
                          TickType_t xTicksToWait );

BaseType_t xQueuePeek( QueueHandle_t xQueue,
                       void *pvBuffer,
                       TickType_t xTicksToWait );

typedef struct {
    uint16_t usSensorID;
    float    fValue;
    TickType_t xTimestamp;
} SensorReading_t;

static QueueHandle_t xSensorQueue;

/* Producer: reads ADC and enqueues a reading every 100 ms */
void vSensorTask( void *pvParameters )
{
    SensorReading_t xReading;
    xReading.usSensorID = ( uint16_t )( uint32_t ) pvParameters;

    for( ;; )
    {
        xReading.fValue     = fReadADC( xReading.usSensorID );
        xReading.xTimestamp = xTaskGetTickCount();

        if( xQueueSend( xSensorQueue, &xReading,
                         pdMS_TO_TICKS( 10 ) ) != pdPASS )
        {
            /* Queue full --- data lost. Increment diagnostic counter. */
            ulSensorDropCount++;
        }

        vTaskDelay( pdMS_TO_TICKS( 100 ) );
    }
}

/* Consumer: blocks until a reading arrives, then processes it */
void vProcessingTask( void *pvParameters )
{
    SensorReading_t xReceived;

    for( ;; )
    {
        if( xQueueReceive( xSensorQueue, &xReceived,
                            portMAX_DELAY ) == pdPASS )
        {
            vApplyFilter( xReceived.usSensorID, xReceived.fValue );
            vLogReading( &xReceived );
        }
    }
}

/* In main(), before starting the scheduler: */
xSensorQueue = xQueueCreate( 16, sizeof( SensorReading_t ) );
configASSERT( xSensorQueue != NULL );
xTaskCreate( vSensorTask, "Sens0", 256, ( void * ) 0, 2, NULL );
xTaskCreate( vSensorTask, "Sens1", 256, ( void * ) 1, 2, NULL );
xTaskCreate( vProcessingTask, "Proc", 512, NULL, 3, NULL );

BaseType_t xQueueSendFromISR( QueueHandle_t xQueue,
                              const void *pvItemToQueue,
                              BaseType_t *pxHigherPriorityTaskWoken );

BaseType_t xQueueReceiveFromISR( QueueHandle_t xQueue,
                                 void *pvBuffer,
                                 BaseType_t *pxHigherPriorityTaskWoken );

static QueueHandle_t xUartRxQueue;

/* UART receive interrupt handler */
void USART2_IRQHandler( void )
{
    BaseType_t xHigherPriorityTaskWoken = pdFALSE;

    if( USART2->SR & USART_SR_RXNE )
    {
        uint8_t ucByte = ( uint8_t )( USART2->DR & 0xFF );

        xQueueSendFromISR( xUartRxQueue, &ucByte,
                           &xHigherPriorityTaskWoken );
    }

    portYIELD_FROM_ISR( xHigherPriorityTaskWoken );
}

/* Deferred processing task: assembles bytes into frames */
void vUartProcessTask( void *pvParameters )
{
    uint8_t ucByte;
    for( ;; )
    {
        if( xQueueReceive( xUartRxQueue, &ucByte,
                            portMAX_DELAY ) == pdPASS )
        {
            vFrameAssembler_AddByte( ucByte );
        }
    }
}

/* Create a set large enough for all member queues */
QueueSetHandle_t xSet = xQueueCreateSet(
    UART_QUEUE_LEN + ADC_QUEUE_LEN + NET_QUEUE_LEN );

/* Add queues to the set */
xQueueAddToSet( xUartQueue, xSet );
xQueueAddToSet( xAdcQueue,  xSet );
xQueueAddToSet( xNetQueue,  xSet );

for( ;; )
{
    QueueSetMemberHandle_t xActiveMember;
    xActiveMember = xQueueSelectFromSet( xSet, portMAX_DELAY );

    if( xActiveMember == xUartQueue )
    {
        xQueueReceive( xUartQueue, &xUartCmd, 0 );
        vHandleUartCommand( &xUartCmd );
    }
    else if( xActiveMember == xAdcQueue )
    {
        xQueueReceive( xAdcQueue, &xAdcReading, 0 );
        vHandleAdcReading( &xAdcReading );
    }
    else if( xActiveMember == xNetQueue )
    {
        xQueueReceive( xNetQueue, &xNetStatus, 0 );
        vHandleNetStatus( &xNetStatus );
    }
}

