#define QUEUE_DEPTH         32
#define NUM_SENSOR_TASKS    2
#define SENSOR_TEMP         0
#define SENSOR_PRESSURE     1
#define SENSOR_VIBRATION    2

typedef struct {
    uint8_t    ucSensorID;
    float      fValue;
    TickType_t xTimestamp;
} SensorCommand_t;

static QueueHandle_t   xCommandQueue;
static TaskHandle_t    xAggregatorHandle;
static volatile uint32_t ulIsrEnqueueFail = 0;
static volatile uint32_t ulTaskEnqueueFail = 0;

static float fSimulateSensor( uint8_t ucID )
{
    /* Replace with actual ADC reads on real hardware */
    TickType_t xT = xTaskGetTickCount();
    switch( ucID )
    {
        case SENSOR_TEMP:     return 20.0f + ( float )( xT % 100 ) * 0.05f;
        case SENSOR_PRESSURE: return 101.3f + ( float )( xT % 50 ) * 0.02f;
        default:              return 0.0f;
    }
}

void vSensorTask( void *pvParameters )
{
    uint8_t ucID = ( uint8_t )( uint32_t ) pvParameters;
    TickType_t xPeriod = ( ucID == SENSOR_TEMP )
                         ? pdMS_TO_TICKS( 100 )   /* 10 Hz */
                         : pdMS_TO_TICKS( 200 );  /* 5 Hz  */
    SensorCommand_t xCmd;
    TickType_t xLastWake = xTaskGetTickCount();

    for( ;; )
    {
        vTaskDelayUntil( &xLastWake, xPeriod );

        xCmd.ucSensorID = ucID;
        xCmd.fValue     = fSimulateSensor( ucID );
        xCmd.xTimestamp = xTaskGetTickCount();

        if( xQueueSend( xCommandQueue, &xCmd,
                         pdMS_TO_TICKS( 10 ) ) != pdPASS )
        {
            ulTaskEnqueueFail++;
        }
    }
}

static void prvVibrationTimerCallback( TimerHandle_t xTimer )
{
    /* Note: software timer callbacks run in the timer-service task
       context, not ISR context. For a true ISR source, use a hardware
       timer interrupt. This example uses the software timer for
       portability. For ISR demonstration, see the hardware variant below. */
    SensorCommand_t xCmd;
    xCmd.ucSensorID = SENSOR_VIBRATION;
    xCmd.fValue     = 0.5f + ( float )( xTaskGetTickCount() % 20 ) * 0.01f;
    xCmd.xTimestamp = xTaskGetTickCount();

    if( xQueueSend( xCommandQueue, &xCmd, 0 ) != pdPASS )
    {
        ulTaskEnqueueFail++;
    }
}

/* Hardware timer ISR variant (STM32F407 TIM2) */
void TIM2_IRQHandler( void )
{
    BaseType_t xWoken = pdFALSE;

    if( TIM2->SR & TIM_SR_UIF )
    {
        TIM2->SR = ~TIM_SR_UIF;   /* Clear interrupt flag (rc_w0: no read-modify-write) */

        SensorCommand_t xCmd;
        xCmd.ucSensorID = SENSOR_VIBRATION;
        xCmd.fValue     = 0.5f;   /* Replace with actual accelerometer read */
        xCmd.xTimestamp = xTaskGetTickCountFromISR();

        if( xQueueSendFromISR( xCommandQueue, &xCmd,
                                &xWoken ) != pdPASS )
        {
            ulIsrEnqueueFail++;
        }
    }

    portYIELD_FROM_ISR( xWoken );
}

void vAggregatorTask( void *pvParameters )
{
    SensorCommand_t xCmd;
    uint32_t ulCounts[ 3 ] = { 0, 0, 0 };
    float    fSums[ 3 ]    = { 0.0f, 0.0f, 0.0f };
    const char *pcNames[]  = { "TEMP", "PRES", "VIBR" };
    UBaseType_t uxHighWater = 0;

    for( ;; )
    {
        if( xQueueReceive( xCommandQueue, &xCmd,
                            portMAX_DELAY ) == pdPASS )
        {
            /* +1 counts the item just removed */
            UBaseType_t uxNow = uxQueueMessagesWaiting( xCommandQueue ) + 1;
            if( uxNow > uxHighWater )
            {
                uxHighWater = uxNow;
            }

            uint8_t ucID = xCmd.ucSensorID;
            if( ucID < 3 )
            {
                ulCounts[ ucID ]++;
                fSums[ ucID ] += xCmd.fValue;
            }

            /* Print summary every 100 messages */
            uint32_t ulTotal = ulCounts[0] + ulCounts[1] + ulCounts[2];
            if( ( ulTotal % 100 ) == 0 )
            {
                printf( "\r\n--- Aggregator Report (total=%lu) ---\r\n",
                        ( unsigned long ) ulTotal );
                for( int i = 0; i < 3; i++ )
                {
                    if( ulCounts[i] > 0 )
                    {
                        printf( "  %s: n=%lu, avg=%.2f\r\n",
                                pcNames[i],
                                ( unsigned long ) ulCounts[i],
                                ( double )( fSums[i] / ulCounts[i] ) );
                    }
                }
                /* Queue diagnostic */
                printf( "  Queue high-water: %lu / %d\r\n",
                        ( unsigned long ) uxHighWater,
                        QUEUE_DEPTH );
                printf( "  Task enqueue fails: %lu\r\n",
                        ( unsigned long ) ulTaskEnqueueFail );
                printf( "  ISR enqueue fails:  %lu\r\n",
                        ( unsigned long ) ulIsrEnqueueFail );
            }
        }
    }
}

