    /* Software timer for vibration (1 kHz) */
    TimerHandle_t xVibTimer = xTimerCreate( "Vib",
                                             pdMS_TO_TICKS( 1 ),
                                             pdTRUE, NULL,
                                             prvVibrationTimerCallback );
    configASSERT( xVibTimer != NULL );
    xTimerStart( xVibTimer, 0 );

    vTaskStartScheduler();

    for( ;; );  /* Should never reach here */
}

