    portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
}

/* Queue holds ADC readings; processing task consumes them */
static QueueHandle_t xAdcQueue;

void ADC_IRQHandler(void)
{
    BaseType_t xHigherPriorityTaskWoken = pdFALSE;
    uint16_t   usReading;

    if (ADC1->SR & ADC_SR_EOC)
    {
        usReading = (uint16_t)ADC1->DR;          /* Read clears EOC   */

        xQueueSendFromISR(xAdcQueue, &usReading,
                          &xHigherPriorityTaskWoken);
    }

    portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
}

void EXTI0_IRQHandler(void)
{
    BaseType_t xHigherPriorityTaskWoken = pdFALSE;

    if (EXTI->PR & EXTI_PR_PR0)
    {
        EXTI->PR = EXTI_PR_PR0;                  /* Clear pending     */

        /* IMMEDIATE: disable motor driver output */
        GPIOB->BSRR = GPIO_BSRR_BR8;            /* PB8 low = disable */
        TIM1->BDTR &= ~TIM_BDTR_MOE;             /* Master output off */

        /* DEFERRED: notify fault handler task */
        xTaskNotifyFromISR(xFaultTaskHandle, FAULT_OVERCURRENT,
                           eSetBits, &xHigherPriorityTaskWoken);
    }

    portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
}

void USART2_IRQHandler(void)
{
    BaseType_t xWoken = pdFALSE;
    uint32_t   ulStatus = USART2->SR;

    if (ulStatus & USART_SR_RXNE)
    {
        uint8_t ucByte = (uint8_t)USART2->DR;
        xStreamBufferSendFromISR(xRxStream, &ucByte, 1, &xWoken);
    }

    if (ulStatus & USART_SR_IDLE)
    {
        (void)USART2->DR;                        /* Clear IDLE flag   */
        xTaskNotifyFromISR(xUartTaskHandle, UART_IDLE_EVENT,
                           eSetBits, &xWoken);
    }

    portYIELD_FROM_ISR(xWoken);                   /* Single yield      */
}

/* Simplified from portmacro.h for Cortex-M4 */
static inline void vPortRaiseBASEPRI(void)
{
    __asm volatile(
        "mov r0, %0      \n"
        "msr basepri, r0  \n"
        ::"i"(configMAX_SYSCALL_INTERRUPT_PRIORITY)
        :"r0"
    );
}

#define RX_BUF_SIZE 256
static uint8_t ucDmaRxBuf[RX_BUF_SIZE] __attribute__((section(".sram")));
static QueueHandle_t xRxQueue;

/* Called once during initialization */
void UART_DMA_Init(void)
{
    /* Configure DMA1 Stream 5, Channel 4 for USART2_RX */
    DMA1_Stream5->CR  = (4U << DMA_SxCR_CHSEL_Pos) /* Channel 4      */
                      | DMA_SxCR_MINC               /* Memory incr    */
                      | DMA_SxCR_CIRC               /* Circular mode  */
                      | DMA_SxCR_TCIE;              /* TC interrupt   */
    DMA1_Stream5->NDTR = RX_BUF_SIZE;
    DMA1_Stream5->PAR  = (uint32_t)&USART2->DR;
    DMA1_Stream5->M0AR = (uint32_t)ucDmaRxBuf;
    DMA1_Stream5->CR  |= DMA_SxCR_EN;              /* Enable stream  */
    USART2->CR3       |= USART_CR3_DMAR;           /* UART RX -> DMA */

    /* Enable UART IDLE interrupt */
    USART2->CR1 |= USART_CR1_IDLEIE;

    NVIC_SetPriority(USART2_IRQn, 6);              /* RTOS-safe      */
    NVIC_EnableIRQ(USART2_IRQn);
    NVIC_SetPriority(DMA1_Stream5_IRQn, 6);
    NVIC_EnableIRQ(DMA1_Stream5_IRQn);
}

/* UART ISR handles idle line detection */
void USART2_IRQHandler(void)
{
    BaseType_t xWoken = pdFALSE;

    if (USART2->SR & USART_SR_IDLE)
    {
        (void)USART2->DR;                          /* Clear IDLE flag */

        /* Calculate bytes received */
        uint16_t usPos = RX_BUF_SIZE - (uint16_t)DMA1_Stream5->NDTR;

        /* Send position to processing task */
        xQueueSendFromISR(xRxQueue, &usPos, &xWoken);
    }

    portYIELD_FROM_ISR(xWoken);
}

void EXTI1_IRQHandler(void)
{
    GPIOC->BSRR = GPIO_BSRR_BS0;    /* PC0 HIGH -- first instruction */

    /* ... ISR body ... */

    GPIOC->BSRR = GPIO_BSRR_BR0;    /* PC0 LOW -- last instruction */

    EXTI->PR = EXTI_PR_PR1;
    portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
}

