/* spi_driver.c */
#include "spi_driver.h"
#include "stm32f4xx_hal.h"
#include "FreeRTOS.h"
#include "semphr.h"
#include <string.h>

static SPI_HandleTypeDef   hspi1;
static SemaphoreHandle_t   spi_mutex;

int spi_init(void)
{
    spi_mutex = xSemaphoreCreateMutex();
    if (!spi_mutex) return -1;

    __HAL_RCC_SPI1_CLK_ENABLE();
    __HAL_RCC_GPIOA_CLK_ENABLE();

    /* PA5 = SCK, PA6 = MISO, PA7 = MOSI (AF5) */
    GPIO_InitTypeDef gpio = {0};
    gpio.Pin       = GPIO_PIN_5 | GPIO_PIN_6 | GPIO_PIN_7;
    gpio.Mode      = GPIO_MODE_AF_PP;
    gpio.Pull      = GPIO_NOPULL;
    gpio.Speed     = GPIO_SPEED_FREQ_HIGH;
    gpio.Alternate = GPIO_AF5_SPI1;
    HAL_GPIO_Init(GPIOA, &gpio);

    hspi1.Instance               = SPI1;
    hspi1.Init.Mode              = SPI_MODE_MASTER;
    hspi1.Init.Direction         = SPI_DIRECTION_2LINES;
    hspi1.Init.DataSize          = SPI_DATASIZE_8BIT;
    hspi1.Init.CLKPolarity       = SPI_POLARITY_LOW;
    hspi1.Init.CLKPhase          = SPI_PHASE_1EDGE;
    hspi1.Init.NSS               = SPI_NSS_SOFT;
    hspi1.Init.BaudRatePrescaler = SPI_BAUDRATEPRESCALER_8;
    hspi1.Init.FirstBit          = SPI_FIRSTBIT_MSB;
    HAL_SPI_Init(&hspi1);

    return 0;
}

static void cs_assert(const spi_device_t *dev)
{
    HAL_GPIO_WritePin((GPIO_TypeDef *)dev->cs_port,
                      dev->cs_pin, GPIO_PIN_RESET);
}

static void cs_deassert(const spi_device_t *dev)
{
    HAL_GPIO_WritePin((GPIO_TypeDef *)dev->cs_port,
                      dev->cs_pin, GPIO_PIN_SET);
}

/* Reconfigure CPOL/CPHA if needed for this device */
static void spi_configure(const spi_device_t *dev)
{
    uint32_t desired_cpol = dev->cpol ? SPI_POLARITY_HIGH
                                      : SPI_POLARITY_LOW;
    uint32_t desired_cpha = dev->cpha ? SPI_PHASE_2EDGE
                                      : SPI_PHASE_1EDGE;
    if (hspi1.Init.CLKPolarity != desired_cpol ||
        hspi1.Init.CLKPhase   != desired_cpha) {
        hspi1.Init.CLKPolarity = desired_cpol;
        hspi1.Init.CLKPhase   = desired_cpha;
        HAL_SPI_Init(&hspi1);
    }
}

int spi_transfer(const spi_device_t *dev, const uint8_t *tx_buf,
                 uint8_t *rx_buf, size_t len, uint32_t timeout_ms)
{
    TickType_t ticks = pdMS_TO_TICKS(timeout_ms);

    if (xSemaphoreTake(spi_mutex, ticks) != pdTRUE) {
        return -1;  /* Bus busy */
    }

    spi_configure(dev);

    cs_assert(dev);

    HAL_StatusTypeDef status;
    if (tx_buf && rx_buf) {
        status = HAL_SPI_TransmitReceive(&hspi1, (uint8_t *)tx_buf,
                                          rx_buf, len, timeout_ms);
    } else if (tx_buf) {
        status = HAL_SPI_Transmit(&hspi1, (uint8_t *)tx_buf,
                                   len, timeout_ms);
    } else {
        /* For read-only, transmit len dummy 0xFF bytes from rx_buf */
        memset(rx_buf, 0xFF, len);
        status = HAL_SPI_TransmitReceive(&hspi1, rx_buf,
                                          rx_buf, len, timeout_ms);
    }

    cs_deassert(dev);

    xSemaphoreGive(spi_mutex);

    return (status == HAL_OK) ? (int)len : -1;
}

int spi_write_then_read(const spi_device_t *dev,
                        const uint8_t *tx_buf, size_t tx_len,
                        uint8_t *rx_buf, size_t rx_len,
                        uint32_t timeout_ms)
{
    TickType_t ticks = pdMS_TO_TICKS(timeout_ms);

    if (xSemaphoreTake(spi_mutex, ticks) != pdTRUE) {
        return -1;  /* Bus busy */
    }

    spi_configure(dev);

    cs_assert(dev);             /* CS stays low for both phases */

    HAL_StatusTypeDef status = HAL_SPI_Transmit(&hspi1, (uint8_t *)tx_buf,
                                                tx_len, timeout_ms);
    if (status == HAL_OK) {
        memset(rx_buf, 0xFF, rx_len);
        status = HAL_SPI_TransmitReceive(&hspi1, rx_buf,
                                          rx_buf, rx_len, timeout_ms);
    }

    cs_deassert(dev);

    xSemaphoreGive(spi_mutex);

    return (status == HAL_OK) ? (int)rx_len : -1;
}

/* Read 256 bytes from SPI flash at given address */
int flash_read_page(uint32_t address, uint8_t *buf)
{
    uint8_t cmd[4];
    cmd[0] = 0x03;                     /* Read Data command  */
    cmd[1] = (address >> 16) & 0xFF;   /* Address byte 2     */
    cmd[2] = (address >>  8) & 0xFF;   /* Address byte 1     */
    cmd[3] = (address >>  0) & 0xFF;   /* Address byte 0     */

    /* Command + address, then 256 data bytes, under one CS assertion:
     * the W25Q128 aborts the read if CS rises between the phases */
    return spi_write_then_read(&flash_dev, cmd, sizeof(cmd),
                               buf, 256, 500);
}

/* i2c_driver.c (excerpts) */
#include "stm32f4xx_hal.h"
#include "FreeRTOS.h"
#include "semphr.h"

static I2C_HandleTypeDef   hi2c1;
static SemaphoreHandle_t   i2c_mutex;

static void i2c_bus_recovery(void)
{
    /* Reconfigure SCL as GPIO output, SDA as GPIO input */
    GPIO_InitTypeDef gpio = {0};
    gpio.Pin   = GPIO_PIN_6;  /* PB6 = SCL */
    gpio.Mode  = GPIO_MODE_OUTPUT_OD;
    gpio.Pull  = GPIO_PULLUP;
    gpio.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(GPIOB, &gpio);

    /* Toggle SCL up to 9 times to free SDA */
    for (int i = 0; i < 9; i++) {
        HAL_GPIO_WritePin(GPIOB, GPIO_PIN_6, GPIO_PIN_RESET);
        HAL_Delay(1);
        HAL_GPIO_WritePin(GPIOB, GPIO_PIN_6, GPIO_PIN_SET);
        HAL_Delay(1);

        /* Check if SDA is released (PB7) */
        if (HAL_GPIO_ReadPin(GPIOB, GPIO_PIN_7) == GPIO_PIN_SET) {
            break;
        }
    }

    /* Generate STOP condition: SDA low-to-high while SCL is high */
    gpio.Pin = GPIO_PIN_7;  /* SDA */
    gpio.Mode = GPIO_MODE_OUTPUT_OD;
    HAL_GPIO_Init(GPIOB, &gpio);
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_7, GPIO_PIN_RESET);
    HAL_Delay(1);
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_7, GPIO_PIN_SET);
    HAL_Delay(1);

    /* Re-initialize I2C peripheral */
    HAL_I2C_Init(&hi2c1);
}

int i2c_read_register(uint8_t dev_addr, uint8_t reg_addr,
                      uint8_t *data, uint16_t len,
                      uint32_t timeout_ms)
{
    TickType_t ticks = pdMS_TO_TICKS(timeout_ms);

    if (xSemaphoreTake(i2c_mutex, ticks) != pdTRUE) {
        return -1;
    }

    HAL_StatusTypeDef status;
    status = HAL_I2C_Mem_Read(&hi2c1, (dev_addr << 1), reg_addr,
                               I2C_MEMADD_SIZE_8BIT,
                               data, len, timeout_ms);

    if (status != HAL_OK) {
        /* Attempt bus recovery and retry once */
        i2c_bus_recovery();
        status = HAL_I2C_Mem_Read(&hi2c1, (dev_addr << 1), reg_addr,
                                   I2C_MEMADD_SIZE_8BIT,
                                   data, len, timeout_ms);
    }

    xSemaphoreGive(i2c_mutex);
    return (status == HAL_OK) ? (int)len : -1;
}

/* Read temperature from LM75 sensor */
float read_temperature(void)
{
    uint8_t raw[2];

    if (i2c_read_register(0x48, 0x00, raw, 2, 100) < 0) {
        return -999.0f;  /* Error sentinel */
    }

    /* LM75: 11-bit signed value, MSB first, upper 11 bits */
    int16_t temp_raw = (int16_t)((raw[0] << 8) | raw[1]);
    temp_raw >>= 5;  /* Right-align 11-bit value */

    return temp_raw * 0.125f;  /* Resolution: 0.125 C per LSB */
}

/* can_driver.h */
#ifndef CAN_DRIVER_H
#define CAN_DRIVER_H

#include <stdint.h>

typedef struct {
    uint32_t id;          /* CAN identifier                    */
    uint8_t  id_type;     /* 0 = standard (11-bit), 1 = ext    */
    uint8_t  dlc;         /* Data length code (0-8)             */
    uint8_t  data[8];     /* Payload                            */
} can_msg_t;

int  can_init(uint32_t bitrate);
int  can_send(const can_msg_t *msg, uint32_t timeout_ms);
int  can_receive(can_msg_t *msg, uint32_t timeout_ms);
int  can_add_filter(uint32_t id, uint32_t mask);

#endif /* CAN_DRIVER_H */

/* can_driver.c */
#include "can_driver.h"
#include "stm32f4xx_hal.h"
#include "FreeRTOS.h"
#include "queue.h"
#include "semphr.h"

static CAN_HandleTypeDef    hcan1;
static QueueHandle_t        can_rx_queue;
static SemaphoreHandle_t    can_tx_sem;

#define CAN_RX_QUEUE_LEN    32

int can_init(uint32_t bitrate)
{
    /* Bit time = 1 (sync) + 11 (BS1) + 2 (BS2) = 14 tq,
     * sample point = 12/14 = 85.7%. CAN1 is clocked from APB1 (42 MHz),
     * so valid bitrates divide 3 MHz: 1 Mbit/s, 500k, 250k, 125k... */
    const uint32_t tq_per_bit = 14U;
    uint32_t pclk1 = HAL_RCC_GetPCLK1Freq();

    if (bitrate == 0 || (pclk1 % (bitrate * tq_per_bit)) != 0) {
        return -1;  /* Bitrate not exactly achievable */
    }
    uint32_t prescaler = pclk1 / (bitrate * tq_per_bit);
    if (prescaler < 1 || prescaler > 1024) return -1;

    can_rx_queue = xQueueCreate(CAN_RX_QUEUE_LEN, sizeof(can_msg_t));
    can_tx_sem   = xSemaphoreCreateCounting(3, 3);  /* 3 TX mailboxes */

    if (!can_rx_queue || !can_tx_sem) return -1;

    __HAL_RCC_CAN1_CLK_ENABLE();
    __HAL_RCC_GPIOD_CLK_ENABLE();

    /* PD0 = CAN1_RX, PD1 = CAN1_TX (AF9) */
    GPIO_InitTypeDef gpio = {0};
    gpio.Pin       = GPIO_PIN_0 | GPIO_PIN_1;
    gpio.Mode      = GPIO_MODE_AF_PP;
    gpio.Pull      = GPIO_NOPULL;
    gpio.Speed     = GPIO_SPEED_FREQ_HIGH;
    gpio.Alternate = GPIO_AF9_CAN1;
    HAL_GPIO_Init(GPIOD, &gpio);

    hcan1.Instance                  = CAN1;
    hcan1.Init.Prescaler            = prescaler;
    hcan1.Init.Mode                 = CAN_MODE_NORMAL;
    hcan1.Init.SyncJumpWidth        = CAN_SJW_1TQ;
    hcan1.Init.TimeSeg1             = CAN_BS1_11TQ;
    hcan1.Init.TimeSeg2             = CAN_BS2_2TQ;
    hcan1.Init.AutoBusOff           = ENABLE;
    hcan1.Init.AutoRetransmission   = ENABLE;
    hcan1.Init.AutoWakeUp           = DISABLE;
    hcan1.Init.TransmitFifoPriority = DISABLE;

    if (HAL_CAN_Init(&hcan1) != HAL_OK) return -1;

    /* Enable RX FIFO0 message pending interrupt */
    HAL_CAN_ActivateNotification(&hcan1,
                                  CAN_IT_RX_FIFO0_MSG_PENDING);
    HAL_CAN_ActivateNotification(&hcan1, CAN_IT_TX_MAILBOX_EMPTY);

    HAL_NVIC_SetPriority(CAN1_RX0_IRQn, 6, 0);
    HAL_NVIC_EnableIRQ(CAN1_RX0_IRQn);
    HAL_NVIC_SetPriority(CAN1_TX_IRQn, 6, 0);
    HAL_NVIC_EnableIRQ(CAN1_TX_IRQn);

    HAL_CAN_Start(&hcan1);
    return 0;
}

/* Standard (11-bit) ID filter; in 32-bit scale STID occupies bits 31:21 */
int can_add_filter(uint32_t id, uint32_t mask)
{
    CAN_FilterTypeDef filter = {0};
    static uint8_t filter_bank = 0;

    filter.FilterBank           = filter_bank++;
    filter.FilterMode           = CAN_FILTERMODE_IDMASK;
    filter.FilterScale          = CAN_FILTERSCALE_32BIT;
    filter.FilterIdHigh         = (id << 5) & 0xFFFF;
    filter.FilterIdLow          = 0;
    filter.FilterMaskIdHigh     = (mask << 5) & 0xFFFF;
    filter.FilterMaskIdLow      = 0;
    filter.FilterFIFOAssignment = CAN_FILTER_FIFO0;
    filter.FilterActivation     = ENABLE;
    filter.SlaveStartFilterBank = 14;   /* Banks 0-13 for CAN1 */

    return (HAL_CAN_ConfigFilter(&hcan1, &filter) == HAL_OK) ? 0 : -1;
}

/* RX FIFO0 callback -- called from CAN1_RX0_IRQHandler */
void HAL_CAN_RxFifo0MsgPendingCallback(CAN_HandleTypeDef *hcan)
{
    BaseType_t xHigherPriorityTaskWoken = pdFALSE;
    CAN_RxHeaderTypeDef header;
    can_msg_t msg;

    if (HAL_CAN_GetRxMessage(hcan, CAN_RX_FIFO0,
                              &header, msg.data) == HAL_OK) {
        msg.id_type = (header.IDE == CAN_ID_EXT) ? 1 : 0;
        msg.id      = msg.id_type ? header.ExtId : header.StdId;
        msg.dlc     = header.DLC;

        xQueueSendFromISR(can_rx_queue, &msg,
                           &xHigherPriorityTaskWoken);
    }

    portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
}

/* TX mailbox released (sent or aborted) -- return it to the pool */
static void can_tx_mailbox_released(void)
{
    BaseType_t xWoken = pdFALSE;
    xSemaphoreGiveFromISR(can_tx_sem, &xWoken);
    portYIELD_FROM_ISR(xWoken);
}

void HAL_CAN_TxMailbox0CompleteCallback(CAN_HandleTypeDef *hcan)
{ (void)hcan; can_tx_mailbox_released(); }
void HAL_CAN_TxMailbox1CompleteCallback(CAN_HandleTypeDef *hcan)
{ (void)hcan; can_tx_mailbox_released(); }
void HAL_CAN_TxMailbox2CompleteCallback(CAN_HandleTypeDef *hcan)
{ (void)hcan; can_tx_mailbox_released(); }
void HAL_CAN_TxMailbox0AbortCallback(CAN_HandleTypeDef *hcan)
{ (void)hcan; can_tx_mailbox_released(); }
void HAL_CAN_TxMailbox1AbortCallback(CAN_HandleTypeDef *hcan)
{ (void)hcan; can_tx_mailbox_released(); }
void HAL_CAN_TxMailbox2AbortCallback(CAN_HandleTypeDef *hcan)
{ (void)hcan; can_tx_mailbox_released(); }

int can_send(const can_msg_t *msg, uint32_t timeout_ms)
{
    if (xSemaphoreTake(can_tx_sem,
                        pdMS_TO_TICKS(timeout_ms)) != pdTRUE) {
        return -1;  /* No mailbox available */
    }

    CAN_TxHeaderTypeDef header = {0};
    if (msg->id_type) {
        header.ExtId = msg->id;
        header.IDE   = CAN_ID_EXT;
    } else {
        header.StdId = msg->id;
        header.IDE   = CAN_ID_STD;
    }
    header.RTR   = CAN_RTR_DATA;
    header.DLC   = msg->dlc;

    uint32_t mailbox;
    if (HAL_CAN_AddTxMessage(&hcan1, &header,
                              (uint8_t *)msg->data,
                              &mailbox) != HAL_OK) {
        xSemaphoreGive(can_tx_sem);
        return -1;
    }
    return 0;
}

int can_receive(can_msg_t *msg, uint32_t timeout_ms)
{
    if (xQueueReceive(can_rx_queue, msg,
                       pdMS_TO_TICKS(timeout_ms)) == pdTRUE) {
        return 0;
    }
    return -1;  /* Timeout */
}

/* hal/fake/uart_hal.c -- Fake HAL with loopback */
#include "uart_hal.h"
#include "uart_rtos.h"   /* uart_rtos_rx_isr(), _tx_isr(), _tc_isr() */
#include <string.h>

/* hal/fake/stm32f4xx_hal.h routes the interrupt-enable macros here:
 *   #define __HAL_UART_ENABLE_IT(h, it)   fake_uart_enable_it(it)
 *   #define __HAL_UART_DISABLE_IT(h, it)  fake_uart_disable_it(it)
 */

#define FAKE_BUF_SIZE 1024

static uint8_t  fake_tx_buf[FAKE_BUF_SIZE];
static uint16_t fake_tx_head;
static uint8_t  fake_rx_byte;      /* "DR" value seen by the RX ISR */
static int      fake_txeie;
static int      loopback_enabled = 0;

/* Simulated UART handle (matches real HAL structure layout) */
UART_HandleTypeDef huart2;

int uart_hal_init(uint32_t baudrate)
{
    fake_tx_head = 0;
    fake_txeie   = 0;
    memset(&huart2, 0, sizeof(huart2));
    (void)baudrate;  /* Baud rate is irrelevant in simulation */
    return 0;
}

uint8_t uart_hal_read_byte(void)
{
    return fake_rx_byte;
}

/* Every byte the driver's TX ISR "writes to DR" is recorded here */
void uart_hal_write_byte(uint8_t byte)
{
    if (fake_tx_head < FAKE_BUF_SIZE) {
        fake_tx_buf[fake_tx_head++] = byte;
    }
    if (loopback_enabled) {
        fake_rx_byte = byte;
        uart_rtos_rx_isr();
    }
}

/* Simulated interrupts: TXE fires until the driver disables it */
void fake_uart_enable_it(uint32_t it)
{
    if (it == UART_IT_TXE) {
        fake_txeie = 1;
        while (fake_txeie) {
            uart_rtos_tx_isr();
        }
    } else if (it == UART_IT_TC) {
        uart_rtos_tc_isr();         /* Shift register is always idle */
    }
}

void fake_uart_disable_it(uint32_t it)
{
    if (it == UART_IT_TXE) {
        fake_txeie = 0;
    }
}

/* Test harness: inject bytes through the driver's RX ISR path */
void fake_uart_inject_rx(const uint8_t *data, uint16_t len)
{
    for (uint16_t i = 0; i < len; i++) {
        fake_rx_byte = data[i];
        uart_rtos_rx_isr();
    }
}

/* Test harness: read what was transmitted */
uint16_t fake_uart_get_tx(uint8_t *buf, uint16_t max_len)
{
    uint16_t count = (fake_tx_head < max_len) ? fake_tx_head : max_len;
    memcpy(buf, fake_tx_buf, count);
    return count;
}

/* Test harness: enable loopback (TX feeds back to RX) */
void fake_uart_set_loopback(int enable)
{
    loopback_enabled = enable;
}

/* test/test_command_parser.c */
#include "unity.h"
#include "uart_api.h"
#include "command_parser.h"
#include <string.h>

/* Provided by fake HAL */
extern void     fake_uart_inject_rx(const uint8_t *data, uint16_t len);
extern uint16_t fake_uart_get_tx(uint8_t *buf, uint16_t max_len);

void setUp(void)
{
    uart_init(UART_PORT_DEBUG, 115200);
}

void test_ping_command_responds_pong(void)
{
    const char *cmd = "PING\r\n";
    fake_uart_inject_rx((const uint8_t *)cmd, strlen(cmd));

    /* Run the parser -- it reads from UART, processes, and writes reply */
    command_parser_tick();

    uint8_t response[64];
    uint16_t len = fake_uart_get_tx(response, sizeof(response) - 1);
    response[len] = '\0';

    TEST_ASSERT_EQUAL_STRING("PONG\r\n", (char *)response);
}

