typedef struct {
    uint32_t r0, r1, r2, r3;
    uint32_t r12, lr, pc, psr;
    uint32_t cfsr, hfsr, mmfar, bfar;
} CrashContext;

/* Stored in backup SRAM to survive reset */
__attribute__((section(".backup_sram")))
volatile CrashContext g_crashCtx;

__attribute__((section(".backup_sram")))
volatile uint32_t g_crashValid;

void HardFault_Handler_C(uint32_t *stackFrame)
{
    g_crashCtx.r0   = stackFrame[0];
    g_crashCtx.r1   = stackFrame[1];
    g_crashCtx.r2   = stackFrame[2];
    g_crashCtx.r3   = stackFrame[3];
    g_crashCtx.r12  = stackFrame[4];
    g_crashCtx.lr   = stackFrame[5];
    g_crashCtx.pc   = stackFrame[6];
    g_crashCtx.psr  = stackFrame[7];

    g_crashCtx.cfsr = SCB->CFSR;
    g_crashCtx.hfsr = SCB->HFSR;
    g_crashCtx.mmfar = SCB->MMFAR;
    g_crashCtx.bfar  = SCB->BFAR;

    g_crashValid = 0xDEADBEEF;

    /* Record to flight recorder */
    FR_Record(FR_EVT_HARD_FAULT, 0xFF,
              (uint16_t)(g_crashCtx.cfsr & 0xFFFF));

    /* Optional: trigger a soft reset to allow post-mortem dump */
    NVIC_SystemReset();
}

/* Assembly wrapper to extract correct stack pointer */
__attribute__((naked))
void HardFault_Handler(void)
{
    __asm volatile(
        "TST   LR, #4          \n"  /* Test bit 2 of EXC_RETURN */
        "ITE   EQ               \n"
        "MRSEQ R0, MSP          \n"  /* Fault used MSP */
        "MRSNE R0, PSP          \n"  /* Fault used PSP */
        "B     HardFault_Handler_C \n"
    );
}

void BackupSRAM_Enable(void)
{
    RCC->AHB1ENR |= RCC_AHB1ENR_BKPSRAMEN;   /* Backup SRAM clock         */
    RCC->APB1ENR |= RCC_APB1ENR_PWREN;       /* PWR clock                 */
    PWR->CR      |= PWR_CR_DBP;              /* Backup-domain write access */

    /* Only needed if contents must survive loss of VDD (VBAT supplied) */
    PWR->CSR |= PWR_CSR_BRE;
    /* Bounded wait: if BRR never sets, continue without VBAT retention */
    for (uint32_t t = 0; t < 100000U && !(PWR->CSR & PWR_CSR_BRR); t++) {}
}

int main(void)
{
    HAL_Init();
    SystemClock_Config();

    /* Enable backup SRAM access (also required by the fault handler) */
    BackupSRAM_Enable();

    if (g_crashValid == 0xDEADBEEF) {
        g_crashValid = 0;
        printf("!!! Previous crash detected !!!\n");
        printf("PC  = 0x%08lX  (faulting instruction)\n",
               (unsigned long)g_crashCtx.pc);
        printf("LR  = 0x%08lX  (return address)\n",
               (unsigned long)g_crashCtx.lr);
        printf("CFSR= 0x%08lX\n",
               (unsigned long)g_crashCtx.cfsr);
        if (g_crashCtx.cfsr & 0x8000)  /* BFSR.BFARVALID */
            printf("BFAR= 0x%08lX\n",
                   (unsigned long)g_crashCtx.bfar);
        if (g_crashCtx.cfsr & 0x80)    /* MMFSR.MMARVALID */
            printf("MMFAR= 0x%08lX\n",
                   (unsigned long)g_crashCtx.mmfar);

        /* Dump flight recorder from previous run */
        FR_Dump();
    }

    FR_Init();
    /* ... create tasks and other initialization ... */

    vTaskStartScheduler();
    for (;;) {}   /* Not reached */
}

