/* Naked trampoline: no compiler prologue may touch the stack before
   the stack pointer is captured. */
__attribute__((naked)) void HardFault_Handler(void)
{
    __asm volatile(
        "TST   LR, #4          \n"  /* Test bit 2 of EXC_RETURN */
        "ITE   EQ               \n"
        "MRSEQ R0, MSP          \n"  /* Fault from handler: use MSP */
        "MRSNE R0, PSP          \n"  /* Fault from task:    use PSP */
        "B     hard_fault_handler_c \n"
    );
}

__attribute__((used)) void hard_fault_handler_c(uint32_t *stack_frame)
{
    volatile uint32_t r0   = stack_frame[0];
    volatile uint32_t r1   = stack_frame[1];
    volatile uint32_t r2   = stack_frame[2];
    volatile uint32_t r3   = stack_frame[3];
    volatile uint32_t r12  = stack_frame[4];
    volatile uint32_t lr   = stack_frame[5];
    volatile uint32_t pc   = stack_frame[6];   /* Faulting instruction */
    volatile uint32_t psr  = stack_frame[7];

    volatile uint32_t cfsr = SCB->CFSR;
    volatile uint32_t hfsr = SCB->HFSR;
    volatile uint32_t mmfar = SCB->MMFAR;
    volatile uint32_t bfar = SCB->BFAR;

    /* Log to UART, backup SRAM, or ITM (Chapter 12) */
    fault_log_to_backup_sram(pc, lr, cfsr, hfsr);

    /* Enter safe state or reset */
    safe_state();
}

void iwdg_init(void)
{
    IWDG->KR  = 0x5555;            /* Unlock PR and RLR registers   */
    IWDG->PR  = IWDG_PR_PR_2;      /* Prescaler /64                 */
    IWDG->RLR = 1000;              /* Reload = 1000                 */
    /* timeout = (64 * 1000) / 32000 = 2.0 seconds                  */

    while (IWDG->SR != 0) {}       /* Wait for registers to update  */
    IWDG->KR  = 0xAAAA;            /* Reload counter (first kick)   */
    IWDG->KR  = 0xCCCC;            /* Start IWDG — cannot be stopped */
}

void iwdg_refresh(void)
{
    IWDG->KR = 0xAAAA;             /* Write reload key              */
}

void wwdg_init(void)
{
    RCC->APB1ENR |= RCC_APB1ENR_WWDGEN;

    /* Prescaler /8, window = 0x50, counter start = 0x7F */
    WWDG->CFR = WWDG_CFR_EWI            /* Enable early wakeup IRQ */
              | WWDG_CFR_WDGTB_0
              | WWDG_CFR_WDGTB_1        /* WDGTB = 11: prescaler /8 */
              | (0x50 & 0x7F);          /* Window value            */

    WWDG->CR  = WWDG_CR_WDGA            /* Activate WWDG           */
              | (0x7F & 0x7F);          /* Counter = 0x7F          */

    NVIC_SetPriority(WWDG_IRQn, 0);     /* Highest priority        */
    NVIC_EnableIRQ(WWDG_IRQn);
}

void WWDG_IRQHandler(void)
{
    WWDG->SR = 0;                        /* Clear EWI flag          */
    /* Last chance: log diagnostic data before reset */
    fault_log_to_backup_sram(0, 0, 0xDEAD0001, 0);
}

#include "FreeRTOS.h"
#include "task.h"
#include "semphr.h"

/* ----- Configuration ----- */
#define MONITOR_PERIOD_MS       500
#define NUM_MONITORED_TASKS     3
#define EXPECTED_CHECKIN_MASK   ((1U << NUM_MONITORED_TASKS) - 1)  /* 0x07 */

/* Bit assignments */
#define TASK_CONTROL_BIT        (1U << 0)
#define TASK_COMMS_BIT          (1U << 1)
#define TASK_LOGGING_BIT        (1U << 2)

/* ----- Shared state ----- */
static volatile uint32_t health_bitmap = 0;
static volatile uint32_t miss_count[NUM_MONITORED_TASKS] = {0};

/* Escalation thresholds */
#define WARN_THRESHOLD          1
#define RECOVER_THRESHOLD       3
#define SAFE_STATE_THRESHOLD    5

/* ----- Check-in API ----- */
void health_checkin(uint32_t task_bit)
{
    /* Atomic set — no mutex needed for single-bit OR on Cortex-M */
    uint32_t primask = __get_PRIMASK();
    __disable_irq();
    health_bitmap |= task_bit;
    __set_PRIMASK(primask);
}

/* ----- Escalation handler ----- */
static void escalate(uint32_t missed_mask)
{
    for (int i = 0; i < NUM_MONITORED_TASKS; i++) {
        if (missed_mask & (1U << i)) {
            miss_count[i]++;

            if (miss_count[i] >= SAFE_STATE_THRESHOLD) {
                /* Level 3: enter safe state and reset */
                fault_log_to_backup_sram(0, 0, missed_mask,
                                         miss_count[i]);
                safe_state();            /* defined in Section 13.8 */
            }
            else if (miss_count[i] >= RECOVER_THRESHOLD) {
                /* Level 2: attempt task restart */
                recover_task(i);         /* defined in Section 13.9 */
            }
            else if (miss_count[i] >= WARN_THRESHOLD) {
                /* Level 1: log warning */
                log_warning("Task %d missed check-in (%lu)\r\n",
                            i, miss_count[i]);
            }
        } else {
            miss_count[i] = 0;          /* Reset on successful check-in */
        }
    }
}

/* ----- Monitor task ----- */
void monitor_task(void *pv)
{
    TickType_t last_wake = xTaskGetTickCount();

    for (;;) {
        vTaskDelayUntil(&last_wake, pdMS_TO_TICKS(MONITOR_PERIOD_MS));

        uint32_t snapshot;
        uint32_t primask = __get_PRIMASK();
        __disable_irq();
        snapshot = health_bitmap;
        health_bitmap = 0;              /* Reset for next period */
        __set_PRIMASK(primask);

        uint32_t missed = EXPECTED_CHECKIN_MASK & ~snapshot;

        if (missed != 0) {
            escalate(missed);           /* safe_state() never returns */
        }

        /* Feed only while the monitor itself is running and escalation
           is still in control. If this task stalls, or safe_state()
           spins with interrupts disabled, the IWDG forces a reset. */
        iwdg_refresh();
    }
}

void vApplicationStackOverflowHook(TaskHandle_t xTask,
                                   char *pcTaskName)
{
    /* WARNING: stack is already corrupted — be minimal here.
       Do NOT call printf, queue operations, or any function
       that allocates stack frames larger than the remaining
       headroom. */

    __disable_irq();

    /* Write fault record to backup SRAM (no stack needed) */
    volatile uint32_t *bkp = (volatile uint32_t *)BKPSRAM_BASE;
    bkp[0] = 0xDEAD57AC;                /* Magic marker        */
    bkp[1] = (uint32_t)xTask;           /* Faulting task handle */
    bkp[2] = (uint32_t)pcTaskName;      /* Task name pointer   */

    /* Enter safe state and reset */
    safe_state();
}

/* FreeRTOSConfig.h */

#ifdef DEBUG
