      do {                                                           \
          if (!(x)) {                                                \
              __disable_irq();                                       \
              assert_log(__FILE__, __LINE__, #x);                    \
              __BKPT(0);    /* Break into debugger if attached */    \
              for (;;) {}   /* Halt if no debugger              */   \
          }                                                          \
      } while (0)
#else
  #define configASSERT(x)                                            \
      do {                                                           \
          if (!(x)) {                                                \
              __disable_irq();                                       \
              fault_log_to_backup_sram(__LINE__,                     \
                  (uint32_t)__FILE__, 0xA55E0000, 0);               \
              NVIC_SystemReset();                                    \
          }                                                          \
      } while (0)
#endif

void assert_log(const char *file, int line, const char *expr)
{
    /* Minimal UART output — polling mode, no interrupts needed */
    uart_poll_print("ASSERT FAILED: ");
    uart_poll_print(file);
    uart_poll_print(":");
    uart_poll_print_int(line);
    uart_poll_print(" — ");
    uart_poll_print(expr);
    uart_poll_print("\r\n");
}

/* Place in .safe_state section — protected by MPU (Chapter 11) */
__attribute__((section(".safe_state"), used))
void safe_state(void)
{
    __disable_irq();

    /* Drive actuator outputs to safe levels using direct register
       access — no HAL, no driver, no RTOS calls. */
    GPIOA->BSRR = GPIO_BSRR_BR_0;     /* PWM output low          */
    GPIOB->BSRR = GPIO_BSRR_BS_4;     /* Contactor relay open    */
    GPIOC->BSRR = GPIO_BSRR_BS_7;     /* Fault LED on            */

    /* Disable DMA channels that might still be driving outputs */
    DMA1_Stream0->CR &= ~DMA_SxCR_EN;
    TIM1->BDTR &= ~TIM_BDTR_MOE;       /* Disable PWM main output */

    /* Log fault to backup SRAM if not already done */

    /* Optional: attempt NVIC_SystemReset() after brief delay,
       or spin here until watchdog resets the system. */
    for (;;) {
        __NOP();
    }
}

.safe_state : {
    KEEP(*(.safe_state))
} > FLASH

static TaskHandle_t comms_handle = NULL;

void recover_task(int task_index)
{
    if (task_index == 1 && comms_handle != NULL) {
        vTaskDelete(comms_handle);
        comms_handle = NULL;

        /* Re-initialize the subsystem state */
        comms_subsystem_init();

        /* Re-create the task */
        xTaskCreate(comms_task, "Comms",
                    COMMS_STACK_SIZE, NULL,
                    COMMS_PRIORITY, &comms_handle);

        log_warning("Task 'Comms' restarted\r\n");
    }
}

void system_reset_with_log(uint32_t fault_code)
{
    __disable_irq();
    fault_log_to_backup_sram(fault_code, 0, 0, 0);
    NVIC_SystemReset();     /* Triggers SCB->AIRCR write */
}

void decode_reset_cause(void)
{
    uint32_t csr = RCC->CSR;
    RCC->CSR |= RCC_CSR_RMVF;          /* Clear flags for next time */

    if (csr & RCC_CSR_LPWRRSTF)  log_info("Reset: low-power\r\n");
    if (csr & RCC_CSR_WWDGRSTF)  log_info("Reset: WWDG\r\n");
    if (csr & RCC_CSR_IWDGRSTF)  log_info("Reset: IWDG\r\n");
    if (csr & RCC_CSR_SFTRSTF)   log_info("Reset: software\r\n");
    if (csr & RCC_CSR_PORRSTF)   log_info("Reset: power-on\r\n");
    if (csr & RCC_CSR_PINRSTF)   log_info("Reset: NRST pin\r\n");
    if (csr & RCC_CSR_BORRSTF)   log_info("Reset: brown-out\r\n");
}

#define FAULT_COUNTER_ADDR  ((volatile uint32_t *)(BKPSRAM_BASE + 0x00))
#define FAULT_VALID_ADDR    ((volatile uint32_t *)(BKPSRAM_BASE + 0x04))
#define FAULT_VALID_MAGIC   0xB007C0DEU
#define MAX_REBOOT_ATTEMPTS 3

void check_reboot_limit(void)
{
    /* Enable backup SRAM clock and power */
    RCC->APB1ENR |= RCC_APB1ENR_PWREN;
    PWR->CR      |= PWR_CR_DBP;
    PWR->CSR     |= PWR_CSR_BRE;        /* Backup regulator for VBAT */
    for (uint32_t t = 0; t < 100000U && !(PWR->CSR & PWR_CSR_BRR); t++) {}
    RCC->AHB1ENR |= RCC_AHB1ENR_BKPSRAMEN;

    if (*FAULT_VALID_ADDR != FAULT_VALID_MAGIC) {
        /* First boot or backup domain lost — initialize */
        *FAULT_COUNTER_ADDR = 0;
        *FAULT_VALID_ADDR   = FAULT_VALID_MAGIC;
    }

    uint32_t count = *FAULT_COUNTER_ADDR;

    if (count >= MAX_REBOOT_ATTEMPTS) {
        /* Too many reboots — enter permanent safe state.
           Requires manual intervention (power cycle with
           service tool) to clear the counter. */
        safe_state();
    }

    *FAULT_COUNTER_ADDR = count + 1;

    /* Cleared later by clear_fault_counter() after a period of
       stable operation */
}

void clear_fault_counter(void)
{
    *FAULT_COUNTER_ADDR = 0;
}

void k_sys_fatal_error_handler(unsigned int reason,
                               const struct arch_esf *esf)
{
    LOG_PANIC();                        /* Flush any buffered log data */
    save_crash_dump(reason, esf);       /* Persist to retained memory  */
    safe_state();
    sys_reboot(SYS_REBOOT_COLD);
}

