    TEST_ASSERT_EQUAL(SENSOR_STATE_TIMEOUT, sensor_get_state(&sensor));
}

/* fake_i2c_hal.c */
#include "hal_api.h"
#include "fake_hal_test.h"
#include <string.h>

#define MAX_TRANSACTIONS 64
#define MAX_DATA_LEN     32

typedef struct {
    uint8_t  addr;
    uint8_t  reg;
    uint8_t  data[MAX_DATA_LEN];
    uint16_t len;
    bool     is_write;
} I2CTransaction;

/* Pre-programmed responses */
static uint8_t        response_data[MAX_TRANSACTIONS][MAX_DATA_LEN];
static HAL_StatusTypeDef response_status[MAX_TRANSACTIONS];
static int            response_count;
static int            response_index;

/* Recorded transactions */
static I2CTransaction recorded[MAX_TRANSACTIONS];
static int            recorded_count;

void fake_i2c_reset(void) {
    memset(response_data, 0, sizeof(response_data));
    memset(recorded, 0, sizeof(recorded));
    response_count = 0;
    response_index = 0;
    recorded_count = 0;
}

void fake_i2c_enqueue_response(const uint8_t *data, uint16_t len,
                                HAL_StatusTypeDef status) {
    memcpy(response_data[response_count], data, len);
    response_status[response_count] = status;
    response_count++;
}

int fake_i2c_get_transaction_count(void) {
    return recorded_count;
}

const I2CTransaction *fake_i2c_get_transaction(int index) {
    return &recorded[index];
}

/* HAL API implementation */
HAL_StatusTypeDef hal_i2c_read(uint8_t addr, uint8_t reg,
                                uint8_t *buf, uint16_t len) {
    /* Record the transaction */
    recorded[recorded_count].addr     = addr;
    recorded[recorded_count].reg      = reg;
    recorded[recorded_count].len      = len;
    recorded[recorded_count].is_write = false;
    recorded_count++;

    /* Return pre-programmed response */
    if (response_index < response_count) {
        memcpy(buf, response_data[response_index], len);
        return response_status[response_index++];
    }
    return HAL_ERROR;  /* no response programmed */
}

HAL_StatusTypeDef hal_i2c_write(uint8_t addr, uint8_t reg,
                                 const uint8_t *data, uint16_t len) {
    recorded[recorded_count].addr     = addr;
    recorded[recorded_count].reg      = reg;
    memcpy(recorded[recorded_count].data, data, len);
    recorded[recorded_count].len      = len;
    recorded[recorded_count].is_write = true;
    recorded_count++;

    if (response_index < response_count) {
        return response_status[response_index++];
    }
    return HAL_OK;
}

void test_temp_sensor_reads_correct_register(void) {
    uint8_t fake_temp[] = {0x01, 0x9A};  /* 25.625 °C */
    fake_i2c_reset();
    fake_i2c_enqueue_response(fake_temp, 2, HAL_OK);

    float temp = temp_sensor_read();

    TEST_ASSERT_FLOAT_WITHIN(0.1f, 25.6f, temp);
    TEST_ASSERT_EQUAL(1, fake_i2c_get_transaction_count());
    const I2CTransaction *txn = fake_i2c_get_transaction(0);
    TEST_ASSERT_EQUAL_HEX8(TEMP_SENSOR_ADDR, txn->addr);
    TEST_ASSERT_EQUAL_HEX8(TEMP_REG, txn->reg);
}

void test_temp_sensor_handles_i2c_bus_error(void) {
    fake_i2c_reset();
    fake_i2c_enqueue_response(NULL, 0, HAL_ERROR);

    float temp = temp_sensor_read();

    TEST_ASSERT_FLOAT_IS_NAN(temp);  /* or sentinel value */
}

/* tests/integration/test_pipeline.c
 * Build with FreeRTOS POSIX simulator port */
#include "FreeRTOS.h"
#include "task.h"
#include "queue.h"
#include "unity.h"
#include <stdio.h>

#define QUEUE_LEN     16
#define NUM_ITEMS     100
#define PRODUCER_PRIO  2
#define CONSUMER_PRIO  3

static QueueHandle_t   data_queue;
static volatile int    consumed_count;
static volatile int    consumed_sum;
static volatile bool   test_complete;

static void producer_task(void *param) {
    for (int i = 1; i <= NUM_ITEMS; i++) {
        int32_t value = i;
        xQueueSend(data_queue, &value, portMAX_DELAY);
    }
    vTaskDelete(NULL);
}

static void consumer_task(void *param) {
    int32_t value;
    while (consumed_count < NUM_ITEMS) {
        if (xQueueReceive(data_queue, &value, pdMS_TO_TICKS(1000))
                == pdTRUE) {
            consumed_count++;
            consumed_sum += value;
        }
    }
    test_complete = true;
    vTaskDelete(NULL);
}

static void test_runner_task(void *param) {
    /* Wait for pipeline completion */
    while (!test_complete) {
        vTaskDelay(pdMS_TO_TICKS(10));
    }
    /* Verify results */
    int expected_sum = (NUM_ITEMS * (NUM_ITEMS + 1)) / 2;
    TEST_ASSERT_EQUAL_INT(NUM_ITEMS, consumed_count);
    TEST_ASSERT_EQUAL_INT(expected_sum, consumed_sum);

    printf("Integration test PASSED\n");
    /* Exit the simulator */
    exit(UNITY_END());
}

int main(void) {
    UNITY_BEGIN();

    data_queue    = xQueueCreate(QUEUE_LEN, sizeof(int32_t));
    consumed_count = 0;
    consumed_sum   = 0;
    test_complete  = false;

    xTaskCreate(producer_task,    "Producer", 1024, NULL,
                PRODUCER_PRIO, NULL);
    xTaskCreate(consumer_task,    "Consumer", 1024, NULL,
                CONSUMER_PRIO, NULL);
    xTaskCreate(test_runner_task, "TestRun",  1024, NULL,
                configMAX_PRIORITIES - 1, NULL);

    vTaskStartScheduler();
    return 1;  /* should not reach here */
}

