/* WRONG: Binary semaphore does not support priority inheritance */
SemaphoreHandle_t xBinarySem;

void vSystemInit(void)
{
    xBinarySem = xSemaphoreCreateBinary();
    xSemaphoreGive(xBinarySem);  /* Initialize as available */
}

/* Low-priority task (priority 1) */
void vSensorTask(void *pvParam)
{
    for (;;) {
        xSemaphoreTake(xBinarySem, portMAX_DELAY);
        /* Access shared I2C bus — takes 5 ms */
        vReadSensorOverI2C();
        xSemaphoreGive(xBinarySem);
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}

/* Medium-priority task (priority 2) — runs heavy computation */
void vProcessingTask(void *pvParam)
{
    for (;;) {
        vPerformHeavyComputation();  /* 20 ms of CPU-bound work */
        vTaskDelay(pdMS_TO_TICKS(50));
    }
}

/* High-priority task (priority 3) — needs the I2C bus */
void vControlTask(void *pvParam)
{
    for (;;) {
        xSemaphoreTake(xBinarySem, portMAX_DELAY);
        /* BUG: If SensorTask holds the semaphore and ProcessingTask
           preempts it, ControlTask is blocked indefinitely */
        vSendCommandOverI2C();
        xSemaphoreGive(xBinarySem);
        vTaskDelay(pdMS_TO_TICKS(10));
    }
}

/* CORRECT: Mutex enables priority inheritance */
SemaphoreHandle_t xI2CMutex;

void vSystemInit(void)
{
    xI2CMutex = xSemaphoreCreateMutex();  /* Created in "given" state */
}

/* Low-priority task (priority 1) */
void vSensorTask(void *pvParam)
{
    for (;;) {
        xSemaphoreTake(xI2CMutex, portMAX_DELAY);
        /* While this task holds the mutex, if ControlTask blocks on it,
           the kernel elevates SensorTask to priority 3 temporarily */
        vReadSensorOverI2C();
        xSemaphoreGive(xI2CMutex);
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}

/* Medium-priority task (priority 2) */
void vProcessingTask(void *pvParam)
{
    for (;;) {
        vPerformHeavyComputation();
        vTaskDelay(pdMS_TO_TICKS(50));
    }
}

/* High-priority task (priority 3) */
void vControlTask(void *pvParam)
{
    for (;;) {
        xSemaphoreTake(xI2CMutex, portMAX_DELAY);
        /* Priority inheritance ensures SensorTask runs at priority 3
           while holding the mutex, preventing ProcessingTask from
           causing unbounded inversion */
        vSendCommandOverI2C();
        xSemaphoreGive(xI2CMutex);
        vTaskDelay(pdMS_TO_TICKS(10));
    }
}

SemaphoreHandle_t xMutexUART;   /* Conceptual order: 1 */
SemaphoreHandle_t xMutexSPI;    /* Conceptual order: 2 */

/* Task A: acquires UART then SPI */
void vTaskA(void *pvParam)
{
    for (;;) {
        xSemaphoreTake(xMutexUART, portMAX_DELAY);  /* Lock 1 */
        xSemaphoreTake(xMutexSPI, portMAX_DELAY);   /* Lock 2 */
        /* BUG: If Task B holds SPI and waits for UART → deadlock */
        vTransferDataUARTtoSPI();
        xSemaphoreGive(xMutexSPI);
        xSemaphoreGive(xMutexUART);
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}

/* Task B: acquires SPI then UART — OPPOSITE ORDER */
void vTaskB(void *pvParam)
{
    for (;;) {
        xSemaphoreTake(xMutexSPI, portMAX_DELAY);   /* Lock 2 */
        xSemaphoreTake(xMutexUART, portMAX_DELAY);  /* Lock 1 */
        /* DEADLOCK possible: holds SPI, waits for UART */
        vTransferDataSPItoUART();
        xSemaphoreGive(xMutexUART);
        xSemaphoreGive(xMutexSPI);
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}

SemaphoreHandle_t xMutexUART;   /* Order: 1 (always acquire first) */
SemaphoreHandle_t xMutexSPI;    /* Order: 2 (always acquire second) */

/* Task A: acquires in order 1 → 2 */
void vTaskA(void *pvParam)
{
    for (;;) {
        xSemaphoreTake(xMutexUART, portMAX_DELAY);
        if (xSemaphoreTake(xMutexSPI, pdMS_TO_TICKS(50)) == pdPASS) {
            vTransferDataUARTtoSPI();
            xSemaphoreGive(xMutexSPI);
        } else {
            /* Timeout: could not acquire second lock, release first */
            /* Log the contention event for diagnostics */
        }
        xSemaphoreGive(xMutexUART);
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}

/* Task B: ALSO acquires in order 1 → 2 (same order as Task A) */
void vTaskB(void *pvParam)
{
    for (;;) {
        xSemaphoreTake(xMutexUART, portMAX_DELAY);    /* Order 1 first */
        if (xSemaphoreTake(xMutexSPI, pdMS_TO_TICKS(50)) == pdPASS) {
            vTransferDataSPItoUART();
            xSemaphoreGive(xMutexSPI);
        } else {
            /* Timeout: release first lock, back off, retry later */
        }
        xSemaphoreGive(xMutexUART);
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}

/* Task created with 256-word (1024-byte) stack */
xTaskCreate(vLogTask, "Log", 256, NULL, 2, NULL);

void vLogTask(void *pvParam)
{
    for (;;) {
        char cBuffer[512];  /* 512 bytes — half the stack, in one frame */
        /* After accounting for context save, local variables in called
           functions, and return addresses, this overflows */
        snprintf(cBuffer, sizeof(cBuffer), "Sensor: %d, Temp: %d",
                 xReadSensor(), xReadTemperature());
        vSendToUART(cBuffer);
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
}

/* Increased stack to 512 words (2048 bytes) with safety margin */
xTaskCreate(vLogTask, "Log", 512, NULL, 2, NULL);

void vLogTask(void *pvParam)
{
    /* Static buffer: allocated in .bss, not on the stack */
    static char cBuffer[512];

    for (;;) {
        snprintf(cBuffer, sizeof(cBuffer), "Sensor: %d, Temp: %d",
                 xReadSensor(), xReadTemperature());
        vSendToUART(cBuffer);

        /* Monitor stack usage in debug builds */
        #if (configCHECK_FOR_STACK_OVERFLOW >= 1)
        {
            UBaseType_t uxHighWaterMark = uxTaskGetStackHighWaterMark(NULL);
            configASSERT(uxHighWaterMark > 50);  /* At least 50 words free */
        }
        #endif

        vTaskDelay(pdMS_TO_TICKS(1000));
    }
}

volatile uint32_t ulSharedCounter = 0;

/* Task A: increments counter */
void vProducerTask(void *pvParam)
{
    for (;;) {
        ulSharedCounter++;  /* NOT atomic: LDR, ADD, STR */
        /* Context switch can occur between LDR and STR.
           If Task B also increments, one increment is lost. */
        vTaskDelay(pdMS_TO_TICKS(10));
    }
}

/* Task B: also increments counter */
void vConsumerTask(void *pvParam)
{
    for (;;) {
        ulSharedCounter++;  /* Same race condition */
        vTaskDelay(pdMS_TO_TICKS(10));
    }
}

uint32_t ulSharedCounter = 0;
SemaphoreHandle_t xCounterMutex;

void vSystemInit(void)
{
    xCounterMutex = xSemaphoreCreateMutex();
}

/* Option A: Mutex protection (preferred for longer operations) */
void vProducerTask(void *pvParam)
{
    for (;;) {
        xSemaphoreTake(xCounterMutex, portMAX_DELAY);
        ulSharedCounter++;
        xSemaphoreGive(xCounterMutex);
        vTaskDelay(pdMS_TO_TICKS(10));
    }
}

/* Option B: Critical section (suitable for single-word operations) */
void vConsumerTask(void *pvParam)
{
    for (;;) {
        taskENTER_CRITICAL();
        ulSharedCounter++;
        taskEXIT_CRITICAL();
        vTaskDelay(pdMS_TO_TICKS(10));
    }
}

SemaphoreHandle_t xDataSemaphore;
QueueHandle_t xDataQueue;

void EXTI0_IRQHandler(void)
{
    HAL_GPIO_EXTI_IRQHandler(GPIO_PIN_0);

    uint32_t ulSensorValue = READ_SENSOR();

    /* WRONG: xQueueSend may block and corrupts kernel state in ISR */
    xQueueSend(xDataQueue, &ulSensorValue, portMAX_DELAY);

    /* WRONG: xSemaphoreTake must never be called from ISR */
    xSemaphoreTake(xDataSemaphore, portMAX_DELAY);
}

SemaphoreHandle_t xDataSemaphore;
QueueHandle_t xDataQueue;

void EXTI0_IRQHandler(void)
{
    BaseType_t xHigherPriorityTaskWoken = pdFALSE;

    HAL_GPIO_EXTI_IRQHandler(GPIO_PIN_0);

    uint32_t ulSensorValue = READ_SENSOR();

    /* CORRECT: FromISR variant, non-blocking */
    xQueueSendFromISR(xDataQueue, &ulSensorValue,
                      &xHigherPriorityTaskWoken);

    /* Request context switch if a higher-priority task was woken */
    portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
}

/* Handler task performs the actual processing */
void vDataHandlerTask(void *pvParam)
{
    uint32_t ulReceived;
    for (;;) {
        if (xQueueReceive(xDataQueue, &ulReceived, portMAX_DELAY) == pdPASS) {
            vProcessSensorData(ulReceived);
        }
    }
}

volatile BaseType_t xDataReady = pdFALSE;

/* ISR sets the flag */
void EXTI0_IRQHandler(void)
{
    HAL_GPIO_EXTI_IRQHandler(GPIO_PIN_0);
    xDataReady = pdTRUE;
}

/* Task polls the flag in a tight loop */
void vDataTask(void *pvParam)
{
    for (;;) {
        while (xDataReady == pdFALSE) {
            /* BUG: spins at 168 MHz doing nothing useful.
               All lower-priority tasks are starved. */
        }
        xDataReady = pdFALSE;
        vProcessData();
    }
}

SemaphoreHandle_t xDataReadySemaphore;

void vSystemInit(void)
{
    xDataReadySemaphore = xSemaphoreCreateBinary();
}

/* ISR signals the semaphore */
void EXTI0_IRQHandler(void)
{
    BaseType_t xHigherPriorityTaskWoken = pdFALSE;
    HAL_GPIO_EXTI_IRQHandler(GPIO_PIN_0);

    xSemaphoreGiveFromISR(xDataReadySemaphore, &xHigherPriorityTaskWoken);
    portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
}

/* Task blocks efficiently until data is ready */
void vDataTask(void *pvParam)
{
    for (;;) {
        /* Task sleeps here, consuming zero CPU.
           Lower-priority tasks run. Idle task runs.
           Tickless idle can engage. */
        if (xSemaphoreTake(xDataReadySemaphore, portMAX_DELAY) == pdPASS) {
            vProcessData();
        }
    }
}

void vSamplingTask(void *pvParam)
{
    for (;;) {
        vReadADCAndStoreResult();  /* Takes 1-5 ms depending on channel */

        /* WRONG: Delay is relative to NOW, not to the last wake.
           Period = execution_time + 100 ms, with jitter. */
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}

void vSamplingTask(void *pvParam)
{
    TickType_t xLastWakeTime;
    const TickType_t xPeriod = pdMS_TO_TICKS(100);

    /* Initialize with the current tick count */
    xLastWakeTime = xTaskGetTickCount();

    for (;;) {
        vReadADCAndStoreResult();  /* Takes 1-5 ms — does not matter */

        /* CORRECT: Delays until xLastWakeTime + xPeriod.
           xLastWakeTime is automatically advanced by xPeriod.
           Period stays 100 ms (no drift) as long as execution plus
           preemption fits within the period. On an overrun the call
           returns immediately (xTaskDelayUntil() returns pdFALSE) and
           the deadline has been missed. */
        vTaskDelayUntil(&xLastWakeTime, xPeriod);
    }
}

void vPeriodicReportTask(void *pvParam)
{
    for (;;) {
        /* BUG: Creates a new one-shot timer every iteration.
           The timer is never deleted. Each creation leaks ~80 bytes. */
        TimerHandle_t xTimer = xTimerCreate(
            "Rpt", pdMS_TO_TICKS(500), pdFALSE, NULL, vReportCallback);
        xTimerStart(xTimer, portMAX_DELAY);

        vTaskDelay(pdMS_TO_TICKS(1000));
    }
    /* After 1000 iterations: ~80 KB leaked. Heap exhausted. */
}

static TimerHandle_t xReportTimer = NULL;

void vSystemInit(void)
{
    /* Create once during init */
    xReportTimer = xTimerCreate(
        "Rpt", pdMS_TO_TICKS(500), pdFALSE, NULL, vReportCallback);
    configASSERT(xReportTimer != NULL);
}

void vPeriodicReportTask(void *pvParam)
{
    for (;;) {
        /* Reuse the same timer — no allocation, no leak */
        xTimerStart(xReportTimer, portMAX_DELAY);
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
}

/* WRONG: CPU-bound task at high priority, never blocks */
void vBadCpuBoundTask(void *pvParam)
{
    for (;;) {
        vDoHeavyComputation();  /* Never yields — idle task starved */
    }
}

/* CORRECT: Task blocks periodically, allowing idle task to run */
void vGoodCpuBoundTask(void *pvParam)
{
    TickType_t xLastWake = xTaskGetTickCount();
    for (;;) {
        vDoHeavyComputation();
        /* Yield for at least 1 tick every iteration */
        vTaskDelayUntil(&xLastWake, pdMS_TO_TICKS(1));
    }
}

/* configLIBRARY_MAX_SYSCALL_INTERRUPT_PRIORITY = 5, so
   configMAX_SYSCALL_INTERRUPT_PRIORITY = 5 << 4 = 0x50 */

void vSetupPeripherals(void)
{
    /* WRONG: Priority 2 is ABOVE configMAX_SYSCALL_INTERRUPT_PRIORITY.
       This ISR can preempt the FreeRTOS kernel! */
    HAL_NVIC_SetPriority(EXTI0_IRQn, 2, 0);
    HAL_NVIC_EnableIRQ(EXTI0_IRQn);
}

void EXTI0_IRQHandler(void)
{
    BaseType_t xWoken = pdFALSE;
    HAL_GPIO_EXTI_IRQHandler(GPIO_PIN_0);
    /* CRASH: Calling FromISR from a priority above the RTOS ceiling */
    xSemaphoreGiveFromISR(xSemaphore, &xWoken);
    portYIELD_FROM_ISR(xWoken);
}

/* configLIBRARY_MAX_SYSCALL_INTERRUPT_PRIORITY = 5, so
   configMAX_SYSCALL_INTERRUPT_PRIORITY = 5 << 4 = 0x50 */

void vSetupPeripherals(void)
{
    /* CORRECT: Priority 5 is at the RTOS ceiling — safe to call
       FromISR APIs. Priorities 5-15 are RTOS-safe. */
    HAL_NVIC_SetPriority(EXTI0_IRQn, 5, 0);
    HAL_NVIC_EnableIRQ(EXTI0_IRQn);

    /* Priority 1 ISR — fast, but must NOT call any FreeRTOS API */
    HAL_NVIC_SetPriority(TIM1_UP_TIM10_IRQn, 1, 0);
    HAL_NVIC_EnableIRQ(TIM1_UP_TIM10_IRQn);
}

