/* Global shared state — no synchronization, hidden dependencies */
volatile float gTemperature;
volatile float gPressure;
volatile uint8_t gDataValid;

void vSensorTask(void *pvParam)
{
    for (;;) {
        gTemperature = fReadTemperatureSensor();
        gPressure = fReadPressureSensor();
        gDataValid = 1;  /* Race: consumer might read between writes */
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}

void vDisplayTask(void *pvParam)
{
    for (;;) {
        if (gDataValid) {
            /* Race: might read new temperature with old pressure */
            vUpdateDisplay(gTemperature, gPressure);
            gDataValid = 0;
        }
        vTaskDelay(pdMS_TO_TICKS(50));
    }
}

typedef struct {
    float fTemperature;
    float fPressure;
} SensorData_t;

static QueueHandle_t xSensorQueue;

void vSystemInit(void)
{
    xSensorQueue = xQueueCreate(5, sizeof(SensorData_t));
    configASSERT(xSensorQueue != NULL);
}

void vSensorTask(void *pvParam)
{
    SensorData_t xData;
    for (;;) {
        xData.fTemperature = fReadTemperatureSensor();
        xData.fPressure = fReadPressureSensor();
        /* Atomic delivery of the complete data structure */
        xQueueSend(xSensorQueue, &xData, pdMS_TO_TICKS(10));
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}

void vDisplayTask(void *pvParam)
{
    SensorData_t xReceived;
    for (;;) {
        /* Blocks until data is available — no polling, no globals */
        if (xQueueReceive(xSensorQueue, &xReceived,
                          portMAX_DELAY) == pdPASS) {
            vUpdateDisplay(xReceived.fTemperature, xReceived.fPressure);
        }
    }
}

void vControlTask(void *pvParam)
{
    for (;;) {
        vTaskDelay(pdMS_TO_TICKS(10));
        xSemaphoreTake(xSharedBusSemaphore, portMAX_DELAY);
        vPerformBusTransaction();     /* 2 ms */
        xSemaphoreGive(xSharedBusSemaphore);
    }
}
