#include <stdint.h>
#include "stm32f4xx.h"
#include "sha256.h"         /* Software SHA-256 (e.g., wrapping mbedtls_sha256) */
#include "ecdsa_verify.h"   /* ECDSA P-256 verify (e.g., mbedTLS or micro-ecc) */

#define APP_SLOT_ADDR       0x08010000U  /* Slot A: sectors 4-7        */
#define APP_SLOT_SIZE       (448U * 1024U)
#define IMG_HDR_SIZE        0x200U       /* Header before vector table */
#define IMG_MAGIC           0x474D4941U
#define STACK_PTR_MIN       0x20000000U
#define STACK_PTR_MAX       0x20020000U

typedef struct {
    uint32_t magic;
    uint32_t image_size;     /* Bytes following the header              */
    uint32_t version;        /* Checked against the anti-rollback counter */
    uint32_t reserved;
    uint8_t  signature[64];  /* ECDSA P-256 (r||s) over
                                SHA-256(first 16 header bytes || image)  */
} image_header_t;

/* Compiled into the bootloader, so it lives in the write-protected
 * sectors 0-1 together with the code that uses it. */
static const uint8_t vendor_public_key[64] = { /* ... */ };

extern uint32_t antirollback_min_version(void);  /* OTP-backed counter */

typedef void (*app_entry_t)(void);

int verify_image(uint32_t slot_addr, uint32_t slot_size)
{
    const image_header_t *hdr = (const image_header_t *)slot_addr;
    sha256_context_t ctx;
    uint8_t digest[32];

    if (hdr->magic != IMG_MAGIC ||
        hdr->image_size == 0U ||
        hdr->image_size > slot_size - IMG_HDR_SIZE) {
        return -1;          /* Malformed header */
    }
    if (hdr->version < antirollback_min_version()) {
        return -1;          /* Rollback attempt */
    }

    sha256_init(&ctx);
    sha256_update(&ctx, (const uint8_t *)hdr, 16U);  /* magic..reserved */
    sha256_update(&ctx, (const uint8_t *)(slot_addr + IMG_HDR_SIZE),
                  hdr->image_size);
    sha256_final(&ctx, digest);

    return (ecdsa_verify_p256(vendor_public_key, digest,
                              hdr->signature) == 0) ? 0 : -1;
}

static void jump_to_application(uint32_t addr)
{
    uint32_t app_stack = *(volatile uint32_t *)addr;
    uint32_t app_reset = *(volatile uint32_t *)(addr + 4U);

    /* Sanity check: stack pointer in SRAM, reset vector inside the slot */
    if (app_stack < STACK_PTR_MIN || app_stack > STACK_PTR_MAX ||
        app_reset < addr || app_reset >= APP_SLOT_ADDR + APP_SLOT_SIZE) {
        /* Invalid image --- halt */
        while (1) { __WFI(); }
    }

    __disable_irq();

    /* Leave no bootloader interrupt source active or pending */
    SysTick->CTRL = 0U;
    SysTick->LOAD = 0U;
    SysTick->VAL  = 0U;
    for (uint32_t i = 0U; i < 8U; i++) {
        NVIC->ICER[i] = 0xFFFFFFFFU;
        NVIC->ICPR[i] = 0xFFFFFFFFU;
    }
    SCB->ICSR = SCB_ICSR_PENDSTCLR_Msk;

    SCB->VTOR = addr;           /* Relocate vector table       */
    __set_MSP(app_stack);       /* Set main stack pointer      */
    __DSB();
    __ISB();
    __enable_irq();             /* Reset state: PRIMASK clear  */

    app_entry_t entry = (app_entry_t)app_reset;
    entry();                    /* Jump to application Reset_Handler */
}

int main(void)
{
    if (verify_image(APP_SLOT_ADDR, APP_SLOT_SIZE) != 0) {
        /* Verification failed --- do not boot.
         * In production: attempt recovery image or signal error via LED. */
        while (1) {
            HAL_GPIO_TogglePin(GPIOD, GPIO_PIN_14); /* Red LED */
            for (volatile int d = 0; d < 500000; d++);
        }
    }

    jump_to_application(APP_SLOT_ADDR + IMG_HDR_SIZE);
    /* Never reached */
    return 0;
}

#include "FreeRTOS.h"
#include "task.h"

/* Shared read-only configuration (aligned for MPU region) */
static const __attribute__((aligned(256))) uint8_t
    g_config[256] = { /* ... populated at init ... */ };

/* Task-private data buffer (aligned for MPU region) */
static __attribute__((aligned(1024))) uint8_t
    g_network_buf[1024];

/* Task function running in unprivileged mode */
static void vNetworkParserTask(void *pvParam)
{
    /* This task can read g_config and read/write g_network_buf.
     * Any access to other memory regions triggers MemManage fault. */
    for (;;) {
        uint16_t len = receive_packet(g_network_buf, sizeof(g_network_buf));
        if (len > 0) {
            parse_packet(g_network_buf, len, g_config);
        }
    }
}

void vCreateRestrictedNetworkTask(void)
{
    static StackType_t xStack[512] __attribute__((aligned(2048)));

    /* Define the three user-configurable MPU regions */
    static const TaskParameters_t xTaskParams = {
        .pvTaskCode   = vNetworkParserTask,
        .pcName       = "NetParse",
        .usStackDepth = 512,
        .pvParameters = NULL,
        .uxPriority   = (tskIDLE_PRIORITY + 2) | portPRIVILEGE_BIT_CLEAR,
        .puxStackBuffer = xStack,
        .xRegions = {
            /* Region 0: task data buffer, read-write, no execute */
            { g_network_buf, 1024,
              portMPU_REGION_READ_WRITE | portMPU_REGION_EXECUTE_NEVER },
            /* Region 1: shared config, read-only, no execute */
            { (void *)g_config, 256,
              portMPU_REGION_READ_ONLY | portMPU_REGION_EXECUTE_NEVER },
            /* Region 2: unused */
            { 0, 0, 0 }
        }
    };

    xTaskCreateRestricted(&xTaskParams, NULL);
}

#include "stm32f4xx_hal.h"
#include "mbedtls/gcm.h"
#include "mbedtls/platform_util.h"
#include <string.h>

#define GCM_NONCE_LEN  12U   /* 96-bit nonce */
#define GCM_TAG_LEN    16U
#define GCM_OVERHEAD   (GCM_NONCE_LEN + GCM_TAG_LEN)

static RNG_HandleTypeDef hrng = { .Instance = RNG };
static mbedtls_gcm_context gcm;  /* Use from one task, or guard with a mutex */

/* key: loaded from the secure element by the caller, which zeroizes its
 * copy (mbedtls_platform_zeroize) once this returns. */
int crypto_init(const uint8_t key[16])
{
    __HAL_RCC_RNG_CLK_ENABLE();
    if (HAL_RNG_Init(&hrng) != HAL_OK) {
        return -1;
    }
    mbedtls_gcm_init(&gcm);
    if (mbedtls_gcm_setkey(&gcm, MBEDTLS_CIPHER_ID_AES, key, 128) != 0) {
        return -1;
    }
    return 0;
}

/* Generate a 96-bit random nonce from the hardware RNG */
static int generate_nonce(uint8_t nonce[GCM_NONCE_LEN])
{
    for (int i = 0; i < 3; i++) {
        uint32_t rnd;
        /* Returns an error on RNG seed/clock faults (SECS/CECS) */
        if (HAL_RNG_GenerateRandomNumber(&hrng, &rnd) != HAL_OK) {
            return -1;
        }
        memcpy(&nonce[i * 4], &rnd, 4);
    }
    return 0;
}

/* Encrypt and authenticate a sensor record.
 * aad: optional data that is authenticated but not encrypted (e.g., record ID).
 * Output: [12-byte nonce][ciphertext][16-byte tag] */
int encrypt_sensor_data(const uint8_t *plaintext, uint32_t len,
                        const uint8_t *aad, uint32_t aad_len,
                        uint8_t *output, uint32_t output_size)
{
    if (output_size < GCM_OVERHEAD || len > output_size - GCM_OVERHEAD) {
        return -1;
    }

    uint8_t *nonce = output;
    uint8_t *ct    = output + GCM_NONCE_LEN;
    uint8_t *tag   = ct + len;

    if (generate_nonce(nonce) != 0) {
        return -1;
    }
    if (mbedtls_gcm_crypt_and_tag(&gcm, MBEDTLS_GCM_ENCRYPT, len,
                                  nonce, GCM_NONCE_LEN, aad, aad_len,
                                  plaintext, ct, GCM_TAG_LEN, tag) != 0) {
        return -1;
    }
    return (int)(len + GCM_OVERHEAD);
}

/* Verify and decrypt a record produced by encrypt_sensor_data().
 * No plaintext is released unless the tag verifies. */
int decrypt_sensor_data(const uint8_t *input, uint32_t input_len,
                        const uint8_t *aad, uint32_t aad_len,
                        uint8_t *plaintext, uint32_t plaintext_size)
{
    if (input_len < GCM_OVERHEAD) {
        return -1;
    }
    uint32_t len = input_len - GCM_OVERHEAD;
    if (len > plaintext_size) {
        return -1;
    }

    if (mbedtls_gcm_auth_decrypt(&gcm, len, input, GCM_NONCE_LEN,
                                 aad, aad_len,
                                 input + GCM_NONCE_LEN + len, GCM_TAG_LEN,
                                 input + GCM_NONCE_LEN, plaintext) != 0) {
        mbedtls_platform_zeroize(plaintext, len);
        return -2;  /* Tampered or corrupted record */
    }
    return (int)len;
}

#include <stdint.h>
#include <string.h>
#include "hmac_sha256.h"   /* Software HMAC-SHA256 implementation */
#include "can_driver.h"    /* RTOS-aware CAN driver from Chapter 9 */

#define HMAC_KEY_LEN      32
#define HMAC_TAG_LEN       4  /* Truncated HMAC for CAN (8-byte payload limit) */
#define CAN_AUTH_MAX_DATA  3
#define SEQ_LO_BITS        6  /* Low counter bits sent on the bus */
#define SEQ_LO_MASK       ((1U << SEQ_LO_BITS) - 1U)

/* Shared secret (in production, load from secure element) */
static const uint8_t hmac_key[HMAC_KEY_LEN] = { /* ... */ };

/* Starts at 1 and only increases. Persist it across resets (or derive a
 * fresh session key at startup) so a value is never reused under one key. */
static uint32_t tx_sequence = 1U;

/* Tag over CAN ID || full 32-bit sequence || length || data.
 * Sender and receiver both call this, so the MAC input is identical. */
static void compute_tag(uint32_t can_id, uint32_t seq, uint8_t len,
                        const uint8_t *data, uint8_t tag[HMAC_TAG_LEN])
{
    uint8_t hmac_input[4 + 4 + 1 + CAN_AUTH_MAX_DATA];
    uint8_t full_hmac[32];

    hmac_input[0] = (uint8_t)(can_id >> 24);
    hmac_input[1] = (uint8_t)(can_id >> 16);
    hmac_input[2] = (uint8_t)(can_id >>  8);
    hmac_input[3] = (uint8_t)(can_id >>  0);
    hmac_input[4] = (uint8_t)(seq >> 24);
    hmac_input[5] = (uint8_t)(seq >> 16);
    hmac_input[6] = (uint8_t)(seq >>  8);
    hmac_input[7] = (uint8_t)(seq >>  0);
    hmac_input[8] = len;
    memcpy(&hmac_input[9], data, len);

    hmac_sha256(hmac_key, HMAC_KEY_LEN, hmac_input, 9U + len, full_hmac);
    memcpy(tag, full_hmac, HMAC_TAG_LEN);
}

/* Build and send an authenticated CAN message.
 * Frame: [len:2 | seq_lo:6][data 0-3 bytes, zero-padded][4-byte HMAC] */
int can_send_authenticated(uint32_t can_id,
                           const uint8_t *data, uint8_t data_len)
{
    if (data_len > CAN_AUTH_MAX_DATA) return -1;
    if (tx_sequence == UINT32_MAX) return -5;  /* Exhausted: re-key */

    uint8_t frame[8];
    memset(frame, 0, sizeof(frame));

    uint32_t seq = tx_sequence++;
    frame[0] = (uint8_t)((data_len << SEQ_LO_BITS) | (seq & SEQ_LO_MASK));
    memcpy(&frame[1], data, data_len);
    compute_tag(can_id, seq, data_len, data, &frame[4]);

    can_msg_t msg = { .id = can_id, .id_type = (can_id > 0x7FFU) ? 1U : 0U,
                      .dlc = 8 };
    memcpy(msg.data, frame, sizeof(frame));
    return can_send(&msg, 10);
}

/* Receive and verify an authenticated CAN message.
 * *last_rx_seq starts at 0 and holds the last accepted sequence number. */
int can_receive_authenticated(uint32_t expected_id,
                              uint8_t *data_out, uint8_t *data_len_out,
                              uint32_t *last_rx_seq)
{
    can_msg_t msg;

    if (can_receive(&msg, 100) != 0) {
        return -1;  /* Timeout or error */
    }
    if (msg.id != expected_id || msg.dlc != 8) return -2;

    const uint8_t *frame = msg.data;
    uint32_t rx_id = msg.id;

    uint8_t len = (uint8_t)(frame[0] >> SEQ_LO_BITS);
    if (len > CAN_AUTH_MAX_DATA) return -2;

    /* Reconstruct the full counter: smallest value > last with these low bits */
    uint32_t last = *last_rx_seq;
    uint32_t seq  = (last & ~SEQ_LO_MASK) | (frame[0] & SEQ_LO_MASK);
    if (seq <= last) {
        seq += SEQ_LO_MASK + 1U;
    }
    if (seq <= last) return -3;  /* Counter space exhausted: re-key */

    uint8_t expected_tag[HMAC_TAG_LEN];
    compute_tag(rx_id, seq, len, &frame[1], expected_tag);

    /* Constant-time comparison of truncated tag */
    uint8_t diff = 0;
    for (int i = 0; i < HMAC_TAG_LEN; i++) {
        diff |= frame[4 + i] ^ expected_tag[i];
    }
    if (diff != 0) return -4;  /* Forged, replayed, or out of sync */

    *last_rx_seq  = seq;       /* Only accepted values advance the window */
    *data_len_out = len;
    memcpy(data_out, &frame[1], len);
    return 0;
}

#include <stdbool.h>
#include <string.h>
#include "stm32f4xx_hal.h"
#include "image_verify.h"   /* verify_image(), image_header_t, IMG_HDR_SIZE,
                               antirollback_advance() (Section 16.2)      */
#include "flash_driver.h"
#include "ota_metadata.h"   /* metadata_load()/metadata_store(): sectors 2-3,
                               two CRC-protected copies                    */

#define SLOT_A_SIZE   (448U * 1024U)   /* Sectors 4-7  */
#define SLOT_B_BASE   0x08080000U      /* Sectors 8-11 */
#define SLOT_B_SIZE   (512U * 1024U)

typedef enum {
    OTA_STATE_IDLE,
    OTA_STATE_DOWNLOADING,
    OTA_STATE_VERIFYING,
    OTA_STATE_SWAPPING,
    OTA_STATE_TESTING,
    OTA_STATE_CONFIRMED,
    OTA_STATE_ROLLBACK,
    OTA_STATE_ERROR
} ota_state_t;

/* Persistent state, stored in the metadata sectors */
typedef struct {
    uint32_t current_version;   /* Confirmed image                     */
    uint32_t pending_version;   /* Installed, not yet confirmed; 0 = none */
    uint32_t swap_requested;    /* Bootloader: install slot B          */
    uint32_t test_boot;         /* New image is on trial               */
} ota_metadata_t;

typedef struct {
    ota_state_t state;
    uint32_t    expected_size;
    uint32_t    received_size;
    uint32_t    expected_version;
} ota_context_t;

static ota_context_t  ota;
static ota_metadata_t meta;
static bool           meta_valid;

/* Call at startup, before ota_begin() or ota_confirm() */
int ota_init(void)
{
    if (metadata_load(&meta) != 0) {
        ota.state = OTA_STATE_ERROR;
        return -1;  /* No valid metadata copy: refuse updates */
    }
    meta_valid = true;
    ota.expected_version = meta.pending_version;
    ota.state = meta.test_boot ? OTA_STATE_TESTING : OTA_STATE_IDLE;
    return 0;
}

int ota_begin(uint32_t image_size, uint32_t version)
{
    if (!meta_valid || ota.state == OTA_STATE_TESTING ||
        ota.state == OTA_STATE_SWAPPING) {
        return -1;  /* No metadata, or current image not yet confirmed */
    }
    if (version <= meta.current_version) {
        return -1;  /* Anti-rollback: reject older versions */
    }
    if (image_size <= IMG_HDR_SIZE || image_size > SLOT_A_SIZE) {
        return -2;  /* Image must fit in slot A once installed */
    }

    /* Erase staging area (slot B) */
    if (flash_erase_slot_b() != 0) {
        return -3;
    }

    ota.state            = OTA_STATE_DOWNLOADING;
    ota.expected_size    = image_size;
    ota.received_size    = 0;
    ota.expected_version = version;
    return 0;
}

int ota_write_chunk(const uint8_t *data, uint32_t len)
{
    if (ota.state != OTA_STATE_DOWNLOADING) return -1;
    if (len > ota.expected_size - ota.received_size) return -2;

    if (flash_write(SLOT_B_BASE + ota.received_size, data, len) != 0) {
        ota.state = OTA_STATE_ERROR;
        return -3;
    }
    ota.received_size += len;

    if (ota.received_size == ota.expected_size) {
        ota.state = OTA_STATE_VERIFYING;
    }
    return 0;
}

int ota_verify_and_apply(void)
{
    if (ota.state != OTA_STATE_VERIFYING) return -1;

    const image_header_t *hdr = (const image_header_t *)SLOT_B_BASE;

    /* SHA-256 + ECDSA P-256 check, identical to the bootloader's.
     * The version is inside the signed header, so it cannot be forged. */
    if (verify_image(SLOT_B_BASE, SLOT_A_SIZE) != 0 ||
        hdr->image_size + IMG_HDR_SIZE != ota.expected_size ||
        hdr->version != ota.expected_version) {
        ota.state = OTA_STATE_ERROR;
        return -2;
    }

    /* Persist the request before resetting; RAM state is lost on reset */
    meta.pending_version = ota.expected_version;
    meta.swap_requested  = 1U;
    meta.test_boot       = 1U;
    if (metadata_store(&meta) != 0) {
        ota.state = OTA_STATE_ERROR;
        return -3;
    }
    ota.state = OTA_STATE_SWAPPING;

    NVIC_SystemReset();  /* Bootloader re-verifies and installs slot B */
    return 0;  /* Never reached */
}

/* Called by the new firmware, after ota_init(), once its self-test passes */
int ota_confirm(void)
{
    if (ota.state != OTA_STATE_TESTING) return -1;

    meta.current_version = meta.pending_version;
    meta.pending_version = 0U;
    meta.test_boot       = 0U;
    if (metadata_store(&meta) != 0) {
        return -2;  /* Still unconfirmed; retry before the watchdog expires */
    }
    antirollback_advance(meta.current_version);  /* OTP counter, if used */
    ota.state = OTA_STATE_CONFIRMED;
    return 0;
}

#include <stdint.h>
#include <string.h>
#include "stm32f4xx_hal.h"
#include "hmac_sha256.h"
#include "uart_driver.h"

#define CMD_FRAME_LEN   20
#define HMAC_TRUNC_LEN   8
#define HMAC_KEY_LEN    32

static const uint8_t cmd_hmac_key[HMAC_KEY_LEN] = {
    /* In production, load from OTP or secure element */
    0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08,
    0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F, 0x10,
    0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18,
    0x19, 0x1A, 0x1B, 0x1C, 0x1D, 0x1E, 0x1F, 0x20
};

static uint32_t last_rx_seq = 0;

typedef struct {
    uint32_t seq_num;
    uint8_t  cmd_code;
    uint8_t  payload[7];
} command_t;

/* Verify and extract a command from a raw frame.
 * Returns 0 on success, negative on failure. */
int verify_command(const uint8_t *frame, command_t *cmd_out)
{
    uint32_t t_start = DWT->CYCCNT;  /* Start cycle counter */

    /* Compute expected HMAC over first 12 bytes */
    uint8_t expected_hmac[32];
    hmac_sha256(cmd_hmac_key, HMAC_KEY_LEN,
                frame, 12, expected_hmac);

    /* Constant-time comparison of truncated tag */
    uint8_t diff = 0;
    for (int i = 0; i < HMAC_TRUNC_LEN; i++) {
        diff |= frame[12 + i] ^ expected_hmac[i];
    }

    uint32_t t_hmac = DWT->CYCCNT - t_start;

    if (diff != 0) {
        uart_printf("AUTH FAIL (HMAC verify: %lu cycles)\r\n", t_hmac);
        return -1;
    }

    /* Extract sequence number (little-endian) */
    uint32_t seq = (uint32_t)frame[0]       |
                   (uint32_t)frame[1] << 8  |
                   (uint32_t)frame[2] << 16 |
                   (uint32_t)frame[3] << 24;

    /* Anti-replay check */
    if (seq <= last_rx_seq) {
        uart_printf("REPLAY REJECTED (seq=%lu, last=%lu)\r\n",
                    seq, last_rx_seq);
        return -2;
    }
    last_rx_seq = seq;

    /* Extract command fields */
    cmd_out->seq_num  = seq;
    cmd_out->cmd_code = frame[4];
    memcpy(cmd_out->payload, &frame[5], 7);

    uart_printf("CMD OK: code=0x%02X seq=%lu (HMAC: %lu cycles, "
                "%.1f us @ 168MHz)\r\n",
                cmd_out->cmd_code, seq,
                t_hmac, (float)t_hmac / 168.0f);
    return 0;
}

/* Main command processing loop (runs as FreeRTOS task) */
void vCommandTask(void *pvParam)
{
    uint8_t frame[CMD_FRAME_LEN];
    command_t cmd;

    /* Enable DWT cycle counter for timing measurements */
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
    DWT->CYCCNT = 0;
    DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;

    for (;;) {
        /* Block until a full 20-byte frame arrives */
        if (uart_receive(frame, CMD_FRAME_LEN,
                         pdMS_TO_TICKS(5000)) == CMD_FRAME_LEN) {
            if (verify_command(frame, &cmd) == 0) {
                execute_command(&cmd);  /* Process valid command */
            }
        }
    }
}

typedef enum {
    EVT_BUTTON_PRESSED,
    EVT_BUTTON_RELEASED,
    EVT_SENSOR_DATA_READY,
    EVT_TIMER_EXPIRED,
    EVT_UART_RX_COMPLETE,
    EVT_STATE_CHANGED,
    EVT_ERROR_DETECTED
} EventType_t;

typedef struct {
    EventType_t eType;
    uint32_t    ulTimestamp;
    uint32_t    ulPayload;
} Event_t;

#define EVENT_QUEUE_LENGTH  32

static QueueHandle_t xEventQueue;

/* ISR posts hardware events */
void EXTI0_IRQHandler(void)
{
    BaseType_t xHigherPriorityTaskWoken = pdFALSE;
    Event_t xEvent = {
        .eType = EVT_BUTTON_PRESSED,
        .ulTimestamp = xTaskGetTickCountFromISR(),
        .ulPayload = 0
    };

    HAL_GPIO_EXTI_IRQHandler(GPIO_PIN_0);
    xQueueSendFromISR(xEventQueue, &xEvent, &xHigherPriorityTaskWoken);
    portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
}

/* Timer callback posts temporal events */
void vSamplingTimerCallback(TimerHandle_t xTimer)
{
    Event_t xEvent = {
        .eType = EVT_TIMER_EXPIRED,
        .ulTimestamp = xTaskGetTickCount(),
        .ulPayload = (uint32_t)pvTimerGetTimerID(xTimer)
    };
    xQueueSend(xEventQueue, &xEvent, 0);
}

typedef void (*EventHandler_t)(const Event_t *pxEvent);

typedef struct {
    EventType_t    eType;
    EventHandler_t pfHandler;
} EventDispatchEntry_t;

static const EventDispatchEntry_t xDispatchTable[] = {
    { EVT_BUTTON_PRESSED,    vHandleButtonPress    },
    { EVT_BUTTON_RELEASED,   vHandleButtonRelease  },
    { EVT_SENSOR_DATA_READY, vHandleSensorData     },
    { EVT_TIMER_EXPIRED,     vHandleTimerExpiry    },
    { EVT_UART_RX_COMPLETE,  vHandleUartRx         },
    { EVT_ERROR_DETECTED,    vHandleError          },
};

#define DISPATCH_TABLE_SIZE \
    (sizeof(xDispatchTable) / sizeof(xDispatchTable[0]))

/* Call from main() before enabling EXTI0 or starting the scheduler,
   so no producer can ever post to a NULL queue handle. */
void vEventDispatcherInit(void)
{
    xEventQueue = xQueueCreate(EVENT_QUEUE_LENGTH, sizeof(Event_t));
    configASSERT(xEventQueue != NULL);
}

void vEventDispatcherTask(void *pvParam)
{
    Event_t xEvent;

    for (;;) {
        if (xQueueReceive(xEventQueue, &xEvent, portMAX_DELAY) == pdTRUE) {
            for (size_t i = 0; i < DISPATCH_TABLE_SIZE; i++) {
                if (xDispatchTable[i].eType == xEvent.eType) {
                    xDispatchTable[i].pfHandler(&xEvent);
                    break;
                }
            }
        }
    }
}

/* --- Active Object infrastructure --- */
typedef struct ActiveObject {
    QueueHandle_t  xQueue;
    TaskHandle_t   xTask;
    void         (*pfInit)(struct ActiveObject *pxAO);
    void         (*pfDispatch)(struct ActiveObject *pxAO,
                               const Event_t *pxEvent);
    uint32_t       ulPostFailures;  /* events lost to a full queue */
} ActiveObject_t;

static void vActiveObjectTask(void *pvParam)
{
    ActiveObject_t *pxAO = (ActiveObject_t *)pvParam;
    Event_t xEvent;

    if (pxAO->pfInit != NULL) {
        pxAO->pfInit(pxAO);
    }

    for (;;) {
        if (xQueueReceive(pxAO->xQueue, &xEvent,
                          portMAX_DELAY) == pdTRUE) {
            pxAO->pfDispatch(pxAO, &xEvent);
        }
    }
}

void vActiveObjectStart(ActiveObject_t *pxAO,
                        const char *pcName,
                        UBaseType_t uxPriority,
                        UBaseType_t uxQueueLen,
                        configSTACK_DEPTH_TYPE uxStackDepth)
{
    pxAO->xQueue = xQueueCreate(uxQueueLen, sizeof(Event_t));
    configASSERT(pxAO->xQueue != NULL);

    BaseType_t xResult = xTaskCreate(
        vActiveObjectTask, pcName, uxStackDepth,
        pxAO, uxPriority, &pxAO->xTask);
    configASSERT(xResult == pdPASS);
}

/* Use xTicksToWait = 0 from timer callbacks and dispatch functions,
   which must never block. */
BaseType_t xActiveObjectPost(ActiveObject_t *pxAO,
                             const Event_t *pxEvent,
                             TickType_t xTicksToWait)
{
    BaseType_t xResult = xQueueSend(pxAO->xQueue, pxEvent,
                                    xTicksToWait);
    if (xResult != pdPASS) {
        taskENTER_CRITICAL();
        pxAO->ulPostFailures++;
        taskEXIT_CRITICAL();
    }
    return xResult;
}

/* --- LED Controller (concrete active object) --- */
typedef enum { LED_STATE_OFF, LED_STATE_ON, LED_STATE_BLINK } LedState_t;

enum { EVT_LED_ON = EVT_ERROR_DETECTED + 1, EVT_LED_OFF, EVT_LED_BLINK };

typedef struct {
    ActiveObject_t xBase;
    LedState_t     eState;
    TimerHandle_t  xBlinkTimer;
} LedController_t;

static LedController_t xLedCtrl;

static void vLedBlinkTimerCb(TimerHandle_t xTimer)
{
    Event_t xEvt = { .eType = EVT_TIMER_EXPIRED };
    /* Timer callbacks run in the timer service task: never block */
    (void)xActiveObjectPost(&xLedCtrl.xBase, &xEvt, 0);
}

static void vLedInit(ActiveObject_t *pxAO)
{
    LedController_t *pxLed = (LedController_t *)pxAO;
    pxLed->eState = LED_STATE_OFF;
    HAL_GPIO_WritePin(GPIOD, GPIO_PIN_12, GPIO_PIN_RESET);
    pxLed->xBlinkTimer = xTimerCreate("LedBlink",
        pdMS_TO_TICKS(500), pdTRUE, NULL, vLedBlinkTimerCb);
}

static void vLedDispatch(ActiveObject_t *pxAO,
                         const Event_t *pxEvent)
{
    LedController_t *pxLed = (LedController_t *)pxAO;

    switch (pxLed->eState) {
    case LED_STATE_OFF:
        if (pxEvent->eType == EVT_LED_ON) {
            HAL_GPIO_WritePin(GPIOD, GPIO_PIN_12, GPIO_PIN_SET);
            pxLed->eState = LED_STATE_ON;
        } else if (pxEvent->eType == EVT_LED_BLINK) {
            xTimerStart(pxLed->xBlinkTimer, 0);
            pxLed->eState = LED_STATE_BLINK;
        }
        break;

    case LED_STATE_ON:
        if (pxEvent->eType == EVT_LED_OFF) {
            HAL_GPIO_WritePin(GPIOD, GPIO_PIN_12, GPIO_PIN_RESET);
            pxLed->eState = LED_STATE_OFF;
        } else if (pxEvent->eType == EVT_LED_BLINK) {
            xTimerStart(pxLed->xBlinkTimer, 0);
            pxLed->eState = LED_STATE_BLINK;
        }
        break;

    case LED_STATE_BLINK:
        if (pxEvent->eType == EVT_TIMER_EXPIRED) {
            HAL_GPIO_TogglePin(GPIOD, GPIO_PIN_12);
        } else if (pxEvent->eType == EVT_LED_OFF) {
            xTimerStop(pxLed->xBlinkTimer, 0);
            HAL_GPIO_WritePin(GPIOD, GPIO_PIN_12, GPIO_PIN_RESET);
            pxLed->eState = LED_STATE_OFF;
        } else if (pxEvent->eType == EVT_LED_ON) {
            xTimerStop(pxLed->xBlinkTimer, 0);
            HAL_GPIO_WritePin(GPIOD, GPIO_PIN_12, GPIO_PIN_SET);
            pxLed->eState = LED_STATE_ON;
        }
        break;
    }
}

/* Initialization */
void vLedControllerCreate(void)
{
    xLedCtrl.xBase.pfInit     = vLedInit;
    xLedCtrl.xBase.pfDispatch = vLedDispatch;
    vActiveObjectStart(&xLedCtrl.xBase, "LED", 2, 16, 256);
}

#define MAX_SUBSCRIBERS_PER_EVENT  8
#define MAX_EVENT_TYPES            16

typedef struct {
    ActiveObject_t *pxSubscribers[MAX_SUBSCRIBERS_PER_EVENT];
    uint8_t         ucCount;
} SubscriptionList_t;

static SubscriptionList_t xSubTable[MAX_EVENT_TYPES];

void vBrokerSubscribe(EventType_t eType, ActiveObject_t *pxSubscriber)
{
    configASSERT(eType < MAX_EVENT_TYPES);
    SubscriptionList_t *pxList = &xSubTable[eType];
    configASSERT(pxList->ucCount < MAX_SUBSCRIBERS_PER_EVENT);
    pxList->pxSubscribers[pxList->ucCount++] = pxSubscriber;
}

void vBrokerPublish(const Event_t *pxEvent)
{
    configASSERT(pxEvent->eType < MAX_EVENT_TYPES);
    SubscriptionList_t *pxList = &xSubTable[pxEvent->eType];

    for (uint8_t i = 0; i < pxList->ucCount; i++) {
        /* Post a copy to each subscriber's queue without blocking;
           a full queue is counted in ulPostFailures */
        (void)xActiveObjectPost(pxList->pxSubscribers[i], pxEvent, 0);
    }
}

/* --- Usage --- */
void vSystemInit(void)
{
    /* Sensor task publishes EVT_SENSOR_DATA_READY */
    /* Data processing and logging both subscribe */
    vBrokerSubscribe(EVT_SENSOR_DATA_READY, &xDataProcessor.xBase);
    vBrokerSubscribe(EVT_SENSOR_DATA_READY, &xDataLogger.xBase);
    vBrokerSubscribe(EVT_ERROR_DETECTED,    &xErrorHandler.xBase);
}

/* Inside sensor active object's dispatch: */
static void vSensorDispatch(ActiveObject_t *pxAO,
                            const Event_t *pxEvent)
{
    if (pxEvent->eType == EVT_TIMER_EXPIRED) {
        uint32_t ulReading = ulReadADC(ADC_CHANNEL_TEMP);
        Event_t xPub = {
            .eType      = EVT_SENSOR_DATA_READY,
            .ulTimestamp = xTaskGetTickCount(),
            .ulPayload  = ulReading
        };
        vBrokerPublish(&xPub);
    }
}

typedef void (*CmdHandler_t)(const uint8_t *pucPayload,
                              uint16_t usLength);

typedef struct {
    uint8_t       ucCmdId;
    uint8_t       ucExpectedLen;   /* 0 = variable length */
    CmdHandler_t  pfHandler;
    const char   *pcName;          /* For debug logging */
} CmdDescriptor_t;

static void vCmdSetLed(const uint8_t *p, uint16_t len);
static void vCmdReadSensor(const uint8_t *p, uint16_t len);
static void vCmdReboot(const uint8_t *p, uint16_t len);
static void vCmdSetConfig(const uint8_t *p, uint16_t len);

static const CmdDescriptor_t xCmdTable[] = {
    { 0x01,  1, vCmdSetLed,      "SET_LED"     },
    { 0x02,  0, vCmdReadSensor,  "READ_SENSOR" },
    { 0x03,  0, vCmdReboot,      "REBOOT"      },
    { 0x10,  4, vCmdSetConfig,   "SET_CONFIG"  },
};

#define CMD_TABLE_SIZE \
    (sizeof(xCmdTable) / sizeof(xCmdTable[0]))

void vCommandProcess(uint8_t ucId,
                     const uint8_t *pucPayload,
                     uint16_t usLength)
{
    for (size_t i = 0; i < CMD_TABLE_SIZE; i++) {
        if (xCmdTable[i].ucCmdId == ucId) {
            /* Validate payload length if fixed-size */
            if (xCmdTable[i].ucExpectedLen != 0 &&
                usLength != xCmdTable[i].ucExpectedLen) {
                vLogError("CMD %s: bad length %u (expected %u)",
                          xCmdTable[i].pcName, usLength,
                          xCmdTable[i].ucExpectedLen);
                return;
            }
            xCmdTable[i].pfHandler(pucPayload, usLength);
            return;
        }
    }
    vLogError("Unknown command ID 0x%02X", ucId);
}

void vSerialCmdTask(void *pvParam)
{
    uint8_t ucRxBuffer[64];

    for (;;) {
        /* Block until a complete frame is received */
        uint16_t usLen = usUartReceiveFrame(ucRxBuffer,
                                            sizeof(ucRxBuffer),
                                            portMAX_DELAY);
        if (usLen >= 1) {
            uint8_t ucId = ucRxBuffer[0];
            vCommandProcess(ucId, &ucRxBuffer[1], usLen - 1);
        }
    }
}

typedef enum {
    MOTOR_IDLE, MOTOR_STARTING, MOTOR_RUNNING,
    MOTOR_STOPPING, MOTOR_FAULT,
    MOTOR_STATE_COUNT
} MotorState_t;

typedef enum {
    ME_START_CMD, ME_SPEED_OK, ME_STOP_CMD,
    ME_FAULT_DETECTED, ME_FAULT_CLEARED, ME_TIMEOUT,
    MOTOR_EVENT_COUNT
} MotorEvent_t;

typedef void (*ActionFunc_t)(void);
typedef bool (*GuardFunc_t)(void);

typedef struct {
    MotorState_t  eNextState;
    ActionFunc_t  pfAction;      /* NULL = no action */
    GuardFunc_t   pfGuard;       /* NULL = always true */
    bool          bValid;        /* false = no transition defined */
} Transition_t;

/* --- Actions --- */
static void vActionEnergizeCoils(void)  { /* PWM start */  }
static void vActionSetRunSpeed(void)    { /* PID engage */ }
static void vActionDeenergize(void)     { /* PWM stop */   }
static void vActionLogFault(void)       { /* Log error */  }
static void vActionResetFault(void)     { /* Clear latch */}

/* --- Guard conditions --- */
static bool bGuardTempOk(void)
{
    return (ulReadTemperature() < TEMP_THRESHOLD);
}

/* --- Transition table: [state][event] --- */
static const Transition_t xTransTable[MOTOR_STATE_COUNT]
                                     [MOTOR_EVENT_COUNT] = {
    /* MOTOR_IDLE */
    [MOTOR_IDLE][ME_START_CMD] =
        { MOTOR_STARTING, vActionEnergizeCoils, bGuardTempOk, true },
    [MOTOR_IDLE][ME_FAULT_DETECTED] =
        { MOTOR_FAULT,    vActionLogFault,      NULL,         true },

    /* MOTOR_STARTING */
    [MOTOR_STARTING][ME_SPEED_OK] =
        { MOTOR_RUNNING,  vActionSetRunSpeed,   NULL,         true },
    [MOTOR_STARTING][ME_TIMEOUT] =
        { MOTOR_FAULT,    vActionLogFault,      NULL,         true },
    [MOTOR_STARTING][ME_FAULT_DETECTED] =
        { MOTOR_FAULT,    vActionLogFault,      NULL,         true },

    /* MOTOR_RUNNING */
    [MOTOR_RUNNING][ME_STOP_CMD] =
        { MOTOR_STOPPING, vActionDeenergize,    NULL,         true },
    [MOTOR_RUNNING][ME_FAULT_DETECTED] =
        { MOTOR_FAULT,    vActionLogFault,      NULL,         true },

    /* MOTOR_STOPPING */
    [MOTOR_STOPPING][ME_SPEED_OK] =    /* speed = 0 */
        { MOTOR_IDLE,     NULL,                 NULL,         true },
    [MOTOR_STOPPING][ME_TIMEOUT] =
        { MOTOR_FAULT,    vActionLogFault,      NULL,         true },

    /* MOTOR_FAULT */
    [MOTOR_FAULT][ME_FAULT_CLEARED] =
        { MOTOR_IDLE,     vActionResetFault,    NULL,         true },
};

/* --- Generic engine --- */
static MotorState_t eCurrentState = MOTOR_IDLE;

void vMotorStateMachineProcess(MotorEvent_t eEvent)
{
    if (eEvent >= MOTOR_EVENT_COUNT) {
        return;  /* Reject out-of-range events */
    }

    const Transition_t *pxTrans =
        &xTransTable[eCurrentState][eEvent];

    /* Unlisted cells are zero-initialized, so bValid is false.
       eNextState cannot be the test: MOTOR_IDLE is also 0. */
    if (!pxTrans->bValid) {
        return;  /* No transition defined for this event */
    }

    /* Evaluate guard condition */
    if (pxTrans->pfGuard != NULL && !pxTrans->pfGuard()) {
        return;  /* Guard blocks transition */
    }

    /* Execute action */
    if (pxTrans->pfAction != NULL) {
        pxTrans->pfAction();
    }

    /* Transition to next state */
    eCurrentState = pxTrans->eNextState;
}

#define SPI_ACQUIRE(mutex, timeout)                          \
    do {                                                     \
        if (xSemaphoreTake((mutex), (timeout)) != pdTRUE) {  \
            vLogError("SPI acquire timeout");                \
            return ERROR_TIMEOUT;                            \
        }                                                    \
    } while (0)

#define SPI_RELEASE(mutex)                                   \
    do { xSemaphoreGive((mutex)); } while (0)

ErrorCode_t eSpiWriteDisplay(const uint8_t *pucData, size_t xLen)
{
    SPI_ACQUIRE(xSpiMutex, pdMS_TO_TICKS(100));
    vSpiSelectChip(SPI_CS_DISPLAY);
    ErrorCode_t eResult = eSpiTransmit(pucData, xLen);
    vSpiDeselectChip(SPI_CS_DISPLAY);
    SPI_RELEASE(xSpiMutex);
    return eResult;
}

typedef struct {
    uint8_t        ucChipSelect;
    const uint8_t *pucTxData;
    uint8_t       *pucRxData;
    size_t         xLength;
    SemaphoreHandle_t xDoneSem;  /* Signaled when complete */
    ErrorCode_t   *peResult;
} SpiBrokerRequest_t;

static QueueHandle_t xSpiBrokerQueue;

void vSpiBrokerTask(void *pvParam)
{
    SpiBrokerRequest_t xReq;
    xSpiBrokerQueue = xQueueCreate(8, sizeof(SpiBrokerRequest_t));
    configASSERT(xSpiBrokerQueue != NULL);

    for (;;) {
        if (xQueueReceive(xSpiBrokerQueue, &xReq,
                          portMAX_DELAY) == pdTRUE) {
            vSpiSelectChip(xReq.ucChipSelect);
            *xReq.peResult = eSpiTransfer(xReq.pucTxData,
                                          xReq.pucRxData,
                                          xReq.xLength);
            vSpiDeselectChip(xReq.ucChipSelect);
            xSemaphoreGive(xReq.xDoneSem);
        }
    }
}

/* Client usage */
ErrorCode_t eSpiBrokerTransact(uint8_t ucCS, const uint8_t *pucTx,
                               uint8_t *pucRx, size_t xLen)
{
    ErrorCode_t eResult;
    SemaphoreHandle_t xDone = xSemaphoreCreateBinary();

    SpiBrokerRequest_t xReq = {
        .ucChipSelect = ucCS,
        .pucTxData    = pucTx,
        .pucRxData    = pucRx,
        .xLength      = xLen,
        .xDoneSem     = xDone,
        .peResult     = &eResult,
    };

    xQueueSend(xSpiBrokerQueue, &xReq, portMAX_DELAY);
    xSemaphoreTake(xDone, portMAX_DELAY);  /* Block until done */
    vSemaphoreDelete(xDone);
    return eResult;
}

#define SENSOR_READY_BIT   (1 << 0)
#define COMM_READY_BIT     (1 << 1)
#define UI_READY_BIT       (1 << 2)
#define ALL_READY_BITS     (SENSOR_READY_BIT | COMM_READY_BIT | \
                            UI_READY_BIT)

static EventGroupHandle_t xStartupSync;

int main(void)
{
    /* Phase 0: Hardware */
    HAL_Init();
    SystemClock_Config();

    /* Phase 1: Drivers */
    vUartDriverInit();
    vSpiDriverInit();
    vAdcDriverInit();

    /* Phase 2: OS objects */
    xStartupSync = xEventGroupCreate();
    configASSERT(xStartupSync != NULL);
    vEventDispatcherInit();       /* Queue exists before EXTI0 fires */

    vLedControllerCreate();       /* Active object */
    vSensorManagerCreate();
    vCommManagerCreate();

    /* Phase 3: Start scheduler */
    vTaskStartScheduler();

    /* Should never reach here */
    for (;;) {}
}

/* Inside sensor manager task */
void vSensorManagerTask(void *pvParam)
{
    /* Phase 4: Task-level init */
    vCalibrateSensor();
    vInitFilterCoefficients();

    /* Signal readiness */
    xEventGroupSetBits(xStartupSync, SENSOR_READY_BIT);

    /* Wait for all subsystems to be ready */
    EventBits_t uxBits = xEventGroupWaitBits(xStartupSync,
                            ALL_READY_BITS, pdFALSE, pdTRUE,
                            pdMS_TO_TICKS(5000));

    if ((uxBits & ALL_READY_BITS) != ALL_READY_BITS) {
        /* Timeout: report which subsystems never became ready,
           then run degraded or request a controlled reset */
        vReportStartupFault(ALL_READY_BITS & ~uxBits);
        vEnterDegradedMode();
    }

    /* Phase 5: Normal operation */
    for (;;) {
        /* ... process events ... */
    }
}

