/* ---- Event definitions ---- */
typedef enum {
    EVT_NONE = 0,
    EVT_TICK_SAMPLE,
    EVT_SENSOR_DATA,
    EVT_PROCESSED_DATA,
    EVT_BUTTON_PRESS,
    EVT_UART_RX,
    EVT_UART_TX_DONE,
    EVT_COMM_CONNECTED,
    EVT_COMM_DISCONNECTED,
    EVT_ERROR,
    EVT_TYPE_COUNT
} EventType_t;

typedef struct {
    EventType_t eType;
    uint32_t    ulTimestamp;
    uint32_t    ulPayload;
} Event_t;

/* ---- Active Object framework ---- */
typedef struct ActiveObject {
    QueueHandle_t xQueue;
    TaskHandle_t  xTask;
    void (*pfInit)(struct ActiveObject *);
    void (*pfDispatch)(struct ActiveObject *, const Event_t *);
} ActiveObject_t;

static void vAOTask(void *pv)
{
    ActiveObject_t *ao = (ActiveObject_t *)pv;
    Event_t evt;
    if (ao->pfInit) ao->pfInit(ao);
    for (;;) {
        if (xQueueReceive(ao->xQueue, &evt,
                          portMAX_DELAY) == pdTRUE) {
            ao->pfDispatch(ao, &evt);
        }
    }
}

static void vAOStart(ActiveObject_t *ao, const char *name,
                     UBaseType_t prio, UBaseType_t qLen,
                     configSTACK_DEPTH_TYPE stack)
{
    ao->xQueue = xQueueCreate(qLen, sizeof(Event_t));
    configASSERT(ao->xQueue);
    xTaskCreate(vAOTask, name, stack, ao, prio, &ao->xTask);
}

static volatile uint32_t ulAODropCount;  /* events lost to full queues */

/* Never blocks: safe from timer callbacks and dispatch functions */
static void vAOPost(ActiveObject_t *ao, const Event_t *e)
{
    if (xQueueSend(ao->xQueue, e, 0) != pdPASS) {
        taskENTER_CRITICAL();
        ulAODropCount++;
        taskEXIT_CRITICAL();
    }
}

/* ---- Pub-Sub Broker ---- */
#define MAX_SUBS  8
typedef struct {
    ActiveObject_t *apSubs[MAX_SUBS];
    uint8_t ucCount;
} SubList_t;

static SubList_t xSubs[EVT_TYPE_COUNT];

static void vSubscribe(EventType_t t, ActiveObject_t *ao)
{
    SubList_t *sl = &xSubs[t];
    configASSERT(sl->ucCount < MAX_SUBS);
    sl->apSubs[sl->ucCount++] = ao;
}

static void vPublish(const Event_t *e)
{
    SubList_t *sl = &xSubs[e->eType];
    for (uint8_t i = 0; i < sl->ucCount; i++) {
        vAOPost(sl->apSubs[i], e);
    }
}

/* ---- Startup synchronization ---- */
#define SENSOR_RDY  (1 << 0)
#define PROC_RDY    (1 << 1)
#define COMM_RDY    (1 << 2)
#define UI_RDY      (1 << 3)
#define ALL_RDY     (SENSOR_RDY | PROC_RDY | COMM_RDY | UI_RDY)

static EventGroupHandle_t xStartupEG;

/* ---- 1. Sensor Manager ---- */
typedef struct {
    ActiveObject_t xBase;
    TimerHandle_t  xSampleTimer;
} SensorMgr_t;

static SensorMgr_t xSensorMgr;

static void vSensorTimerCb(TimerHandle_t t)
{
    Event_t e = { .eType = EVT_TICK_SAMPLE,
                  .ulTimestamp = xTaskGetTickCount() };
    vAOPost(&xSensorMgr.xBase, &e);
}

static void vSensorInit(ActiveObject_t *ao)
{
    SensorMgr_t *s = (SensorMgr_t *)ao;
    s->xSampleTimer = xTimerCreate("Samp", pdMS_TO_TICKS(250),
                                   pdTRUE, NULL, vSensorTimerCb);
    configASSERT(s->xSampleTimer);
    xEventGroupSetBits(xStartupEG, SENSOR_RDY);

    /* The sensor is the data source: hold sampling until every
       active object has initialized */
    EventBits_t bits = xEventGroupWaitBits(xStartupEG, ALL_RDY,
                                           pdFALSE, pdTRUE,
                                           pdMS_TO_TICKS(2000));
    if ((bits & ALL_RDY) != ALL_RDY) {
        /* Degraded start: UI shows the red error LED */
        Event_t err = { .eType = EVT_ERROR,
                        .ulTimestamp = xTaskGetTickCount(),
                        .ulPayload = ALL_RDY & ~bits };
        vPublish(&err);
    }
    xTimerStart(s->xSampleTimer, 0);
}

static void vSensorDispatch(ActiveObject_t *ao, const Event_t *e)
{
    if (e->eType == EVT_TICK_SAMPLE) {
        /* Read ADC (internal temperature sensor on ADC1 CH16) */
        uint32_t raw = 2048; /* Replace with ulReadADC() */
        Event_t pub = { .eType = EVT_SENSOR_DATA,
                        .ulTimestamp = xTaskGetTickCount(),
                        .ulPayload = raw };
        vPublish(&pub);
    }
}

/* ---- 2. Data Processor ---- */
typedef struct {
    ActiveObject_t xBase;
    uint32_t       ulFilterAccum;
    uint8_t        ucSampleCount;
} DataProc_t;

static DataProc_t xDataProc;

static void vDataProcInit(ActiveObject_t *ao)
{
    (void)ao;
    xEventGroupSetBits(xStartupEG, PROC_RDY);
}

static void vDataProcDispatch(ActiveObject_t *ao, const Event_t *e)
{
    DataProc_t *dp = (DataProc_t *)ao;
    if (e->eType == EVT_SENSOR_DATA) {
        dp->ulFilterAccum += e->ulPayload;
        dp->ucSampleCount++;
        if (dp->ucSampleCount >= 4) {
            uint32_t avg = dp->ulFilterAccum / 4;
            dp->ulFilterAccum = 0;
            dp->ucSampleCount = 0;
            Event_t pub = { .eType = EVT_PROCESSED_DATA,
                            .ulTimestamp = xTaskGetTickCount(),
                            .ulPayload = avg };
            vPublish(&pub);
        }
    }
}

/* ---- 3. Comm Manager (with state machine) ---- */
typedef enum {
    COMM_DISCONNECTED, COMM_CONNECTED, COMM_ERROR
} CommState_t;

typedef struct {
    ActiveObject_t xBase;
    CommState_t    eState;
} CommMgr_t;

static CommMgr_t xCommMgr;

static void vCommDispatch(ActiveObject_t *ao, const Event_t *e)
{
    CommMgr_t *cm = (CommMgr_t *)ao;

    switch (cm->eState) {
    case COMM_DISCONNECTED:
        if (e->eType == EVT_UART_RX) {
            /* Received handshake byte */
            cm->eState = COMM_CONNECTED;
            Event_t pub = { .eType = EVT_COMM_CONNECTED,
                            .ulTimestamp = xTaskGetTickCount() };
            vPublish(&pub);
        }
        break;

    case COMM_CONNECTED:
        if (e->eType == EVT_PROCESSED_DATA) {
            /* Transmit processed data over UART */
            uint8_t buf[4];
            memcpy(buf, &e->ulPayload, 4);
            /* usUartTransmit(buf, 4); */
        } else if (e->eType == EVT_ERROR) {
            cm->eState = COMM_ERROR;
        }
        break;

    case COMM_ERROR:
        if (e->eType == EVT_UART_RX) {
            cm->eState = COMM_CONNECTED;
        }
        break;
    }
}

static void vCommInit(ActiveObject_t *ao)
{
    CommMgr_t *cm = (CommMgr_t *)ao;
    cm->eState = COMM_DISCONNECTED;
    xEventGroupSetBits(xStartupEG, COMM_RDY);
}

/* ---- 4. UI Controller ---- */
typedef struct {
    ActiveObject_t xBase;
    bool           bLedOn;
} UiCtrl_t;

static UiCtrl_t xUiCtrl;

static void vUiInit(ActiveObject_t *ao)
{
    UiCtrl_t *ui = (UiCtrl_t *)ao;
    ui->bLedOn = false;
    xEventGroupSetBits(xStartupEG, UI_RDY);
}

static void vUiDispatch(ActiveObject_t *ao, const Event_t *e)
{
    UiCtrl_t *ui = (UiCtrl_t *)ao;

    switch (e->eType) {
    case EVT_PROCESSED_DATA:
        /* Blink green LED (PD12) to show activity */
        HAL_GPIO_TogglePin(GPIOD, GPIO_PIN_12);
        break;

    case EVT_BUTTON_PRESS:
        /* Toggle orange LED (PD13) on button press */
        ui->bLedOn = !ui->bLedOn;
        HAL_GPIO_WritePin(GPIOD, GPIO_PIN_13,
                          ui->bLedOn ? GPIO_PIN_SET
                                     : GPIO_PIN_RESET);
        break;

    case EVT_COMM_CONNECTED:
        /* Blue LED (PD15) on when connected */
        HAL_GPIO_WritePin(GPIOD, GPIO_PIN_15, GPIO_PIN_SET);
        break;

    case EVT_COMM_DISCONNECTED:
        HAL_GPIO_WritePin(GPIOD, GPIO_PIN_15, GPIO_PIN_RESET);
        break;

    case EVT_ERROR:
        /* Red LED (PD14) on for error */
        HAL_GPIO_WritePin(GPIOD, GPIO_PIN_14, GPIO_PIN_SET);
        break;

    default:
        break;
    }
}

/* ---- Button ISR ---- */
void EXTI0_IRQHandler(void)
{
    BaseType_t xWake = pdFALSE;
    Event_t e = { .eType = EVT_BUTTON_PRESS,
                  .ulTimestamp = xTaskGetTickCountFromISR() };
    HAL_GPIO_EXTI_IRQHandler(GPIO_PIN_0);
    xQueueSendFromISR(xUiCtrl.xBase.xQueue, &e, &xWake);
    portYIELD_FROM_ISR(xWake);
}

/* ---- Startup ---- */
int main(void)
{
    HAL_Init();
    SystemClock_Config();
    /* GPIO, UART, ADC init omitted for brevity; enable the EXTI0 IRQ
       only after the UI queue has been created below */

    memset(xSubs, 0, sizeof(xSubs));
    xStartupEG = xEventGroupCreate();
    configASSERT(xStartupEG);

    /* Create active objects */
    xSensorMgr.xBase.pfInit     = vSensorInit;
    xSensorMgr.xBase.pfDispatch = vSensorDispatch;
    vAOStart(&xSensorMgr.xBase, "Sensor", 3, 16, 256);

    xDataProc.xBase.pfInit     = vDataProcInit;
    xDataProc.xBase.pfDispatch = vDataProcDispatch;
    vAOStart(&xDataProc.xBase, "DataProc", 2, 16, 256);

    xCommMgr.xBase.pfInit     = vCommInit;
    xCommMgr.xBase.pfDispatch = vCommDispatch;
    vAOStart(&xCommMgr.xBase, "Comm", 2, 16, 256);

    xUiCtrl.xBase.pfInit     = vUiInit;
    xUiCtrl.xBase.pfDispatch = vUiDispatch;
    vAOStart(&xUiCtrl.xBase, "UI", 1, 16, 256);

    /* Register subscriptions */
    vSubscribe(EVT_SENSOR_DATA,    &xDataProc.xBase);
    vSubscribe(EVT_PROCESSED_DATA, &xCommMgr.xBase);
    vSubscribe(EVT_PROCESSED_DATA, &xUiCtrl.xBase);
    vSubscribe(EVT_COMM_CONNECTED, &xUiCtrl.xBase);
    vSubscribe(EVT_ERROR,          &xUiCtrl.xBase);

    HAL_NVIC_EnableIRQ(EXTI0_IRQn);  /* UI queue now exists */
    vTaskStartScheduler();
    for (;;) {}
}

/* MISRA C:2012 compliant task function */

/* Rule 8.4: Compatible declaration shall be visible */
extern void vTemperatureMonitorTask(void *pvParameters);

/* Rule 8.13: pvParameters could be const, but FreeRTOS API
   defines the signature as void* — deviation documented */
void vTemperatureMonitorTask(void *pvParameters)
{
    /* Rule 21.3: No dynamic allocation — use stack variables */
    TickType_t xLastWakeTime;
    float fTemperature;
    float fThreshold;
    BaseType_t xAlarmActive;

    /* Rule 11.4 deviation: cast required for hardware register access */
    /* Deviation documented in project deviation log, entry DEV-0042 */

    xLastWakeTime = xTaskGetTickCount();
    fThreshold = 85.0F;   /* Rule 10.3: float constant, no double */
    xAlarmActive = pdFALSE;

    /* Rule 2.1: loop body is reachable */
    for (;;)   /* Rule 14.2: compliant for-loop for infinite loop */
    {
        vTaskDelayUntil(&xLastWakeTime, pdMS_TO_TICKS(100U));

        fTemperature = fReadTemperatureSensor();

        if (fTemperature >= fThreshold)    /* Rule 13.5: no side effects */
        {
            if (xAlarmActive == pdFALSE)
            {
                vActivateAlarm();
                xAlarmActive = pdTRUE;
            }
            /* else: alarm already active, no action */
        }
        else
        {
            if (xAlarmActive == pdTRUE)
            {
                vDeactivateAlarm();
                xAlarmActive = pdFALSE;
            }
            /* else: alarm already inactive, no action */
        }
    }

    /* Rule 2.1: this point is unreachable — acceptable for
       RTOS tasks per project deviation DEV-0003 */
}

if ((fTemperature >= fHighThreshold) && (xAlarmActive == pdFALSE)) {
    vActivateAlarm();
}

/* Enable SMP with 2 cores (e.g., RP2040, ESP32-S3) */
#define configNUMBER_OF_CORES    2

/* Allow tasks of different priorities to run at the same time
   on different cores (0 = only equal-priority tasks run together) */
#define configRUN_MULTIPLE_PRIORITIES    1

/* Enable core affinity API */
#define configUSE_CORE_AFFINITY    1

/*
 * SMP Task Affinity Example — FreeRTOS on RP2040
 *
 * Demonstrates pinning tasks to specific cores for
 * deterministic placement alongside freely migrating tasks.
 */

/* Core affinity masks */
#define CORE_0_MASK    (1 << 0)    /* 0b01 — core 0 only  */
#define CORE_1_MASK    (1 << 1)    /* 0b10 — core 1 only  */
#define ANY_CORE_MASK  (0x03)      /* 0b11 — either core   */

static void vSensorTask(void *pvParameters)
{
    /* This task is pinned to core 0, which owns the SPI peripheral */
    for (;;) {
        int16_t sample = sensor_read_spi();
        xQueueSend(xSensorQueue, &sample, portMAX_DELAY);
    }
}

static void vControlTask(void *pvParameters)
{
    /* This task is pinned to core 0 for deterministic latency */
    int16_t sample;
    for (;;) {
        xQueueReceive(xSensorQueue, &sample, portMAX_DELAY);
        pid_update(&controller, sample);
        actuator_write(controller.output);
    }
}

static void vLoggingTask(void *pvParameters)
{
    /* This task may run on either core — load-balanced by scheduler */
    for (;;) {
        LogEntry_t entry;
        xQueueReceive(xLogQueue, &entry, portMAX_DELAY);
        sd_card_write(&entry, sizeof(entry));
    }
}

int main(void)
{
    hardware_init();

    xSensorQueue = xQueueCreate(16, sizeof(int16_t));
    xLogQueue    = xQueueCreate(64, sizeof(LogEntry_t));

    TaskHandle_t xSensorHandle, xControlHandle, xLogHandle;

    xTaskCreate(vSensorTask,  "Sensor",  256, NULL, 3, &xSensorHandle);
    xTaskCreate(vControlTask, "Control", 256, NULL, 4, &xControlHandle);
    xTaskCreate(vLoggingTask, "Log",     512, NULL, 1, &xLogHandle);

    /* Pin sensor and control tasks to core 0 */
    vTaskCoreAffinitySet(xSensorHandle,  CORE_0_MASK);
    vTaskCoreAffinitySet(xControlHandle, CORE_0_MASK);

    /* Allow logging task to migrate freely */
    vTaskCoreAffinitySet(xLogHandle, ANY_CORE_MASK);

    vTaskStartScheduler();
    for (;;) {}
}

/* SMP critical section — same API as single-core FreeRTOS */
taskENTER_CRITICAL();
/* Local interrupts masked AND the kernel spinlocks held,
   so no other core can be inside a critical section */
shared_counter++;
taskEXIT_CRITICAL();

#include "hardware/sync.h"

static spin_lock_t *pxCounterLock;

void counter_init(void)
{
    pxCounterLock = spin_lock_init(spin_lock_claim_unused(true));
}

void counter_increment(void)
{
    /* Masks local interrupts and spins for the lock */
    uint32_t ulSaved = spin_lock_blocking(pxCounterLock);
    shared_counter++;
    spin_unlock(pxCounterLock, ulSaved);
}

/* amp_ipc.h — shared-memory layout for the Section 19.4 example */
#ifndef AMP_IPC_H
#define AMP_IPC_H

#include <stdbool.h>
#include <stdint.h>
#include <string.h>
#include "stm32h7xx.h"

#define HSEM_ID_IPC_NOTIFY  0U
#define IPC_RING_SLOTS      64U   /* Must be power of 2 */
#define IPC_SLOT_SIZE       32U   /* Bytes per slot      */

typedef struct {
    uint32_t timestamp_us;
    float    speed_rpm;
    float    current_a;
    float    temperature_c;
} Telemetry_t;

typedef struct {
    volatile uint32_t head;       /* Written only by the producer */
    volatile uint32_t tail;       /* Written only by the consumer */
    uint8_t           slot[IPC_RING_SLOTS][IPC_SLOT_SIZE];
} IPC_SlotRing_t;

typedef struct {
    volatile uint32_t initialized;  /* 0xDEADBEEF once the M7 is done */
    IPC_SlotRing_t    telemetry_ring;
} SharedIPC_t;

static inline bool ipc_ring_push(volatile IPC_SlotRing_t *r,
                                 const void *data, uint32_t len)
{
    uint32_t h = r->head;
    uint32_t next = (h + 1U) & (IPC_RING_SLOTS - 1U);
    if (len > IPC_SLOT_SIZE || next == r->tail) return false;
    __DMB();                      /* Tail read before slot overwrite */
    memcpy((void *)r->slot[h], data, len);
    __DMB();                      /* Payload visible before head    */
    r->head = next;
    return true;
}

static inline bool ipc_ring_pop(volatile IPC_SlotRing_t *r,
                                void *data, uint32_t len)
{
    uint32_t t = r->tail;
    if (len > IPC_SLOT_SIZE || t == r->head) return false;
    __DMB();                      /* Head read before payload read  */
    memcpy(data, (const void *)r->slot[t], len);
    __DMB();                      /* Payload read before slot reuse */
    r->tail = (t + 1U) & (IPC_RING_SLOTS - 1U);
    return true;
}

static inline void ipc_shared_init(volatile SharedIPC_t *ipc)
{
    ipc->telemetry_ring.head = 0U;
    ipc->telemetry_ring.tail = 0U;
    __DMB();
    ipc->initialized = 0xDEADBEEFU;
}

#endif /* AMP_IPC_H */

/*
 * STM32H755 AMP Boot — Cortex-M7 main.c
 *
 * M7 initializes clocks, shared resources, and IPC,
 * then releases the M4 core from reset.
 */

#include "stm32h7xx_hal.h"
#include "FreeRTOS.h"
#include "task.h"
#include "amp_ipc.h"

/* Located in SRAM3 — shared, non-cacheable */
volatile SharedIPC_t *pxSharedIPC =
    (volatile SharedIPC_t *)0x30040000UL;

static void vM7ControlTask(void *pvParameters)
{
    for (;;) {
        /* Real-time motor control at 10 kHz */
        ulTaskNotifyTake(pdTRUE, portMAX_DELAY);
        motor_foc_update(&motor_state);

        /* Send telemetry to M4 via shared ring buffer */
        ipc_ring_push(&pxSharedIPC->telemetry_ring,
                       &motor_state.telemetry,
                       sizeof(Telemetry_t));

        /* SRAM3 is MPU non-cacheable, so a barrier suffices; a
           cacheable buffer would also need SCB_CleanDCache_by_Addr() */
        __DMB();

        /* Signal M4 via hardware semaphore interrupt */
        HAL_HSEM_FastTake(HSEM_ID_IPC_NOTIFY);
        HAL_HSEM_Release(HSEM_ID_IPC_NOTIFY, 0);
    }
}

int main(void)
{
    HAL_Init();
    SystemClock_Config();   /* 480 MHz M7, 240 MHz M4 */

    /* Configure MPU: SRAM3 as non-cacheable, shared */
    mpu_configure_shared_region(0x30040000UL, 32 * 1024);

    /* Initialize shared IPC region before M4 boots */
    ipc_shared_init(pxSharedIPC);

    /* Enable HSEM clock; only the M4 enables the notification */
    __HAL_RCC_HSEM_CLK_ENABLE();

    /* Release Cortex-M4 from reset */
    HAL_RCCEx_EnableBootCore(RCC_BOOT_C2);

    xTaskCreate(vM7ControlTask, "M7Ctrl", 512, NULL, 5, NULL);
    vTaskStartScheduler();
    for (;;) {}
}

/*
 * STM32H755 AMP Boot — Cortex-M4 main.c
 *
 * M4 runs FreeRTOS with a data processing task that
 * receives telemetry from M7 via shared memory.
 */

#include "stm32h7xx_hal.h"
#include "FreeRTOS.h"
#include "task.h"
#include "amp_ipc.h"

volatile SharedIPC_t *pxSharedIPC =
    (volatile SharedIPC_t *)0x30040000UL;

static TaskHandle_t xProcessTaskHandle;

void HSEM2_IRQHandler(void)
{
    HAL_HSEM_IRQHandler();
    /* The HAL disarms the notification on each event; re-arm it */
    HAL_HSEM_ActivateNotification(__HAL_HSEM_SEMID_TO_MASK(
        HSEM_ID_IPC_NOTIFY));
    BaseType_t xHigherPriorityTaskWoken = pdFALSE;
    vTaskNotifyGiveFromISR(xProcessTaskHandle,
                           &xHigherPriorityTaskWoken);
    portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
}

static void vM4ProcessTask(void *pvParameters)
{
    Telemetry_t telemetry;
    for (;;) {
        ulTaskNotifyTake(pdTRUE, portMAX_DELAY);
        /* Order the notification before reading shared data
           (the M4 has no data cache, so no invalidate is needed) */
        __DMB();
        while (ipc_ring_pop(&pxSharedIPC->telemetry_ring,
                             &telemetry,
                             sizeof(Telemetry_t))) {
            data_log_store(&telemetry);
            diagnostics_update(&telemetry);
        }
    }
}

int main(void)
{
    HAL_Init();
    /* M4 clock already configured by M7 */

    /* Wait for M7 to initialize shared IPC */
    while (pxSharedIPC->initialized != 0xDEADBEEFU) {
        __NOP();
    }

    __HAL_RCC_HSEM_CLK_ENABLE();
    HAL_HSEM_ActivateNotification(__HAL_HSEM_SEMID_TO_MASK(
        HSEM_ID_IPC_NOTIFY));
    HAL_NVIC_EnableIRQ(HSEM2_IRQn);

    xTaskCreate(vM4ProcessTask, "M4Proc", 512, NULL, 3,
                &xProcessTaskHandle);
    vTaskStartScheduler();
    for (;;) {}
}

void mpu_configure_shared_region(uint32_t base, uint32_t size)
{
    MPU_Region_InitTypeDef mpu_init = {0};
    HAL_MPU_Disable();

    mpu_init.Enable           = MPU_REGION_ENABLE;
    mpu_init.BaseAddress      = base;
    mpu_init.Size             = MPU_REGION_SIZE_32KB;
    mpu_init.AccessPermission = MPU_REGION_FULL_ACCESS;
    mpu_init.IsBufferable     = MPU_ACCESS_NOT_BUFFERABLE;
    mpu_init.IsCacheable      = MPU_ACCESS_NOT_CACHEABLE;
    mpu_init.IsShareable      = MPU_ACCESS_SHAREABLE;
    mpu_init.TypeExtField     = MPU_TEX_LEVEL1;
    mpu_init.Number           = MPU_REGION_NUMBER5;
    mpu_init.SubRegionDisable = 0x00;
    mpu_init.DisableExec      = MPU_INSTRUCTION_ACCESS_DISABLE;
    HAL_MPU_ConfigRegion(&mpu_init);

    HAL_MPU_Enable(MPU_PRIVILEGED_DEFAULT);
}

/*
 * Lock-Free SPSC Ring Buffer for Inter-Core Communication
 *
 * Producer: Core 0 (M7)    Consumer: Core 1 (M4)
 * Buffer resides in shared non-cacheable SRAM3.
 * Memory barriers ensure cross-core visibility.
 */

#include <stdint.h>
#include <string.h>

#define RING_SIZE    256   /* Must be power of 2 */
#define RING_MASK    (RING_SIZE - 1)

typedef struct {
    volatile uint32_t write_idx;   /* Modified only by producer */
    volatile uint32_t read_idx;    /* Modified only by consumer */
    uint8_t           buffer[RING_SIZE];
} SPSC_Ring_t;

/* Producer (Core 0): push one byte */
static inline int ring_push(SPSC_Ring_t *ring, uint8_t data)
{
    uint32_t w = ring->write_idx;
    uint32_t next_w = (w + 1) & RING_MASK;

    if (next_w == ring->read_idx) {
        return -1;  /* Full */
    }

    /* Consumer must have finished with the slot before we overwrite it */
    __DMB();
    ring->buffer[w] = data;

    /* Ensure data is written before index update is visible */
    __DMB();
    ring->write_idx = next_w;

    return 0;
}

/* Consumer (Core 1): pop one byte */
static inline int ring_pop(SPSC_Ring_t *ring, uint8_t *data)
{
    uint32_t r = ring->read_idx;

    if (r == ring->write_idx) {
        return -1;  /* Empty */
    }

    /* Acquire: load write_idx before reading the slot it publishes */
    __DMB();
    *data = ring->buffer[r];

    /* Ensure data is read before index update is visible */
    __DMB();
    ring->read_idx = (r + 1) & RING_MASK;

    return 0;
}

/* Zephyr IPC service — send a message to the remote core */
const struct device *ipc = DEVICE_DT_GET(DT_NODELABEL(ipc0));
struct ipc_ept ep;
ipc_service_open_instance(ipc);
ipc_service_register_endpoint(ipc, &ep, &ep_cfg);
ipc_service_send(&ep, data, sizeof(data));

/* Give each shared variable its own 32-byte cache line */
__attribute__((aligned(32))) static uint32_t core0_counter;
__attribute__((aligned(32))) static uint32_t core1_counter;

/* ipc_shared.h — shared between M7 and M4 projects */

#ifndef IPC_SHARED_H
#define IPC_SHARED_H

#include <stdint.h>

#define IPC_RING_SIZE     128   /* Must be power of 2 */
#define IPC_RING_MASK     (IPC_RING_SIZE - 1)
#define HSEM_ID_IPC_NOTIFY  0   /* HSEM slot for IPC */

typedef struct {
    uint32_t timestamp_us;
    int16_t  sensor_value;
    uint16_t sequence;
} __attribute__((packed)) SensorSample_t;

typedef struct {
    volatile uint32_t write_idx;
    volatile uint32_t read_idx;
    SensorSample_t    samples[IPC_RING_SIZE];
} IPC_Ring_t;

typedef struct {
    volatile uint32_t initialized;   /* Set to 0xDEADBEEF by M7 */
    volatile uint32_t m4_ready;      /* Set to 0xCAFECAFE by M4 */
    IPC_Ring_t        sensor_ring;
    volatile uint32_t latency_timestamp; /* For latency measurement */
} SharedIPC_t;

/* Ring buffer operations — inlined for both cores */
static inline int ipc_ring_push(volatile IPC_Ring_t *ring,
                                const SensorSample_t *sample)
{
    uint32_t w = ring->write_idx;
    uint32_t next_w = (w + 1) & IPC_RING_MASK;
    if (next_w == ring->read_idx) return -1; /* Full */
    __DMB();
    ring->samples[w] = *sample;
    __DMB();
    ring->write_idx = next_w;
    return 0;
}

static inline int ipc_ring_pop(volatile IPC_Ring_t *ring,
                               SensorSample_t *sample)
{
    uint32_t r = ring->read_idx;
    if (r == ring->write_idx) return -1; /* Empty */
    __DMB();
    *sample = ring->samples[r];
    __DMB();
    ring->read_idx = (r + 1) & IPC_RING_MASK;
    return 0;
}

#endif /* IPC_SHARED_H */

/* main_m7.c — Cortex-M7 firmware (Core 0) */

#include "stm32h7xx_hal.h"
#include "FreeRTOS.h"
#include "task.h"
#include "ipc_shared.h"

#define SHARED_IPC_ADDR  0x30040000UL

volatile SharedIPC_t *pxIPC =
    (volatile SharedIPC_t *)SHARED_IPC_ADDR;

static uint16_t usSequence = 0;

/* GPIO pin toggle for oscilloscope latency measurement */
#define LATENCY_PIN_PORT   GPIOB
#define LATENCY_PIN        GPIO_PIN_0

static void vProducerTask(void *pv)
{
    TickType_t xLastWake = xTaskGetTickCount();

    for (;;) {
        vTaskDelayUntil(&xLastWake, pdMS_TO_TICKS(1)); /* 1 kHz */

        SensorSample_t sample;
        sample.timestamp_us = DWT->CYCCNT / (SystemCoreClock / 1000000);
        sample.sensor_value = (int16_t)(HAL_ADC_GetValue(&hadc1) & 0xFFFF);
        sample.sequence     = usSequence++;

        /* Toggle pin HIGH — start of latency measurement */
        HAL_GPIO_WritePin(LATENCY_PIN_PORT, LATENCY_PIN, GPIO_PIN_SET);

        if (ipc_ring_push(&pxIPC->sensor_ring, &sample) == 0) {
            /* Ring stores complete before the notification (SRAM3
               is MPU non-cacheable, so no cache clean is needed) */
            __DMB();
            /* Notify M4 via HSEM release */
            HAL_HSEM_FastTake(HSEM_ID_IPC_NOTIFY);
            HAL_HSEM_Release(HSEM_ID_IPC_NOTIFY, 0);
        }

        HAL_GPIO_WritePin(LATENCY_PIN_PORT, LATENCY_PIN, GPIO_PIN_RESET);
    }
}

int main(void)
{
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_ADC1_Init();

    /* Enable DWT cycle counter for timestamps */
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
    DWT->CYCCNT = 0;
    DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;

    /* Configure shared region as non-cacheable */
    mpu_configure_shared_region(SHARED_IPC_ADDR, 32 * 1024);

    /* Initialize shared IPC structure */
    memset((void *)pxIPC, 0, sizeof(SharedIPC_t));
    __DMB();
    pxIPC->initialized = 0xDEADBEEFUL;

    /* Enable HSEM */
    __HAL_RCC_HSEM_CLK_ENABLE();

    /* Release M4 from reset */
    HAL_RCCEx_EnableBootCore(RCC_BOOT_C2);

    /* Wait for M4 to signal ready */
    while (pxIPC->m4_ready != 0xCAFECAFEUL) { __NOP(); }

    xTaskCreate(vProducerTask, "Producer", 256, NULL, 4, NULL);
    vTaskStartScheduler();
    for (;;) {}
}

/* main_m4.c — Cortex-M4 firmware (Core 1) */

#include "stm32h7xx_hal.h"
#include "FreeRTOS.h"
#include "task.h"
#include "ipc_shared.h"

#define SHARED_IPC_ADDR  0x30040000UL

volatile SharedIPC_t *pxIPC =
    (volatile SharedIPC_t *)SHARED_IPC_ADDR;

static TaskHandle_t xConsumerHandle;

/* Statistics */
static uint32_t ulMessagesReceived = 0;
static uint32_t ulSequenceErrors   = 0;
static uint16_t usExpectedSeq      = 0;

/* GPIO for latency measurement — toggle LOW on receive */
#define LATENCY_PIN_PORT   GPIOB
#define LATENCY_PIN        GPIO_PIN_1

void HSEM2_IRQHandler(void)
{
    HAL_HSEM_IRQHandler();
    /* The HAL disarms the notification on each event; re-arm it */
    HAL_HSEM_ActivateNotification(
        __HAL_HSEM_SEMID_TO_MASK(HSEM_ID_IPC_NOTIFY));
    BaseType_t xWoken = pdFALSE;
    vTaskNotifyGiveFromISR(xConsumerHandle, &xWoken);
    portYIELD_FROM_ISR(xWoken);
}

static void vConsumerTask(void *pv)
{
    SensorSample_t sample;

    for (;;) {
        ulTaskNotifyTake(pdTRUE, portMAX_DELAY);
        /* Order the notification before reading shared data */
        __DMB();

        while (ipc_ring_pop(&pxIPC->sensor_ring, &sample) == 0) {
            /* Toggle pin LOW — end of latency measurement */
            HAL_GPIO_WritePin(LATENCY_PIN_PORT, LATENCY_PIN,
                              GPIO_PIN_RESET);

            ulMessagesReceived++;

            /* Verify sequence continuity */
            if (sample.sequence != usExpectedSeq) {
                ulSequenceErrors++;
            }
            usExpectedSeq = sample.sequence + 1;

            /* Process sample (filtering, logging, etc.) */
            process_sample(&sample);

            HAL_GPIO_WritePin(LATENCY_PIN_PORT, LATENCY_PIN,
                              GPIO_PIN_SET);
        }
    }
}

int main(void)
{
    HAL_Init();

    /* Wait for M7 to initialize shared memory */
    while (pxIPC->initialized != 0xDEADBEEFUL) { __NOP(); }

    MX_GPIO_Init();

    /* Enable HSEM notification for this core */
    __HAL_RCC_HSEM_CLK_ENABLE();
    HAL_HSEM_ActivateNotification(
        __HAL_HSEM_SEMID_TO_MASK(HSEM_ID_IPC_NOTIFY));
    HAL_NVIC_SetPriority(HSEM2_IRQn, 5, 0);
    HAL_NVIC_EnableIRQ(HSEM2_IRQn);

    xTaskCreate(vConsumerTask, "Consumer", 256, NULL, 3,
                &xConsumerHandle);

    /* Signal M7 that M4 is ready */
    __DMB();
    pxIPC->m4_ready = 0xCAFECAFEUL;

    vTaskStartScheduler();
    for (;;) {}
}

/*
 * Single-core AMP simulation on STM32F407
 *
 * Two tasks communicate through a shared SPSC ring buffer
 * in a dedicated RAM array, emulating inter-core communication.
 */

#include "FreeRTOS.h"
#include "task.h"
#include <string.h>

#define IPC_RING_SIZE  128
#define IPC_RING_MASK  (IPC_RING_SIZE - 1)

typedef struct {
    uint32_t timestamp;
    int16_t  value;
    uint16_t sequence;
} Sample_t;

/* Simulated shared memory region */
static volatile uint32_t write_idx = 0;
static volatile uint32_t read_idx  = 0;
static Sample_t ring_buffer[IPC_RING_SIZE];

static int sim_push(const Sample_t *s)
{
    uint32_t w = write_idx;
    uint32_t nw = (w + 1) & IPC_RING_MASK;
    if (nw == read_idx) return -1;
    __DMB();
    ring_buffer[w] = *s;
    __DMB();
    write_idx = nw;
    return 0;
}

static int sim_pop(Sample_t *s)
{
    uint32_t r = read_idx;
    if (r == write_idx) return -1;
    __DMB();
    *s = ring_buffer[r];
    __DMB();
    read_idx = (r + 1) & IPC_RING_MASK;
    return 0;
}

static TaskHandle_t xConsumerHandle;

static void vSimProducer(void *pv)
{
    uint16_t seq = 0;
    TickType_t xLast = xTaskGetTickCount();
    for (;;) {
        vTaskDelayUntil(&xLast, pdMS_TO_TICKS(1));
        Sample_t s = { xTaskGetTickCount(), (int16_t)(seq * 3), seq++ };
        if (sim_push(&s) == 0) {
            xTaskNotifyGive(xConsumerHandle);
        }
    }
}

static void vSimConsumer(void *pv)
{
    Sample_t s;
    uint16_t expected = 0;
    uint32_t errors = 0;
    for (;;) {
        ulTaskNotifyTake(pdTRUE, portMAX_DELAY);
        while (sim_pop(&s) == 0) {
            if (s.sequence != expected) errors++;
            expected = s.sequence + 1;
        }
    }
}

int main(void)
{
    HAL_Init();
    SystemClock_Config();

    xTaskCreate(vSimProducer, "SimProd", 256, NULL, 3, NULL);
    xTaskCreate(vSimConsumer, "SimCons", 256, NULL, 2,
                &xConsumerHandle);
    vTaskStartScheduler();
    for (;;) {}
}

